files.ref_ot_prefix.sv:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// Explicit log-depth adders for the 1.2 GHz V4.1 ROM element (W10).
//
// Written as behavioural `a + b` or `a + inc`, yosys/ABC maps these adders as carry ripples (chains of MAJ or
// OR cells) even with ADDER_MAP_FILE cleared: measured at ORFS WC, 0.833 ns, a 28-bit add inside the element
// took 920 ps and a 24-bit rounding increment a chain of ten OR4/OR5 cells (W10 and W13, 2026-09-30).  Here each
// Kogge-Stone prefix level is a (* keep *) net, so synthesis must keep log2(W) levels.
//
// ot_v41_ksadd: s = a + b + cin (W bits), cout.
// ot_v41_inc:   y = a + inc (W bits), co (the carry out of the top bit).
// ---------------------------------------------------------------------------
module ref_ot_v41_ksadd #(
    parameter integer W = 28
) (
    input  wire [W-1:0] a,
    input  wire [W-1:0] b,
    input  wire         cin,
    output wire [W-1:0] s,
    output wire         cout
);
    localparam integer L = $clog2(W + 1);
    // position 0 is the carry-in; bit i of the operands is position i + 1
    (* keep *) wire [W:0] g [0:L];
    (* keep *) wire [W:0] p [0:L];
    assign g[0] = {a & b, cin};
    assign p[0] = {a ^ b, 1'b0};
    genvar l, i;
    generate
        for (l = 0; l < L; l = l + 1) begin : g_lv
            for (i = 0; i <= W; i = i + 1) begin : g_b
                if (i >= (1 << l)) begin : g_c
                    assign g[l + 1][i] = g[l][i] | (p[l][i] & g[l][i - (1 << l)]);
                    assign p[l + 1][i] = p[l][i] & p[l][i - (1 << l)];
                end else begin : g_p
                    assign g[l + 1][i] = g[l][i];
                    assign p[l + 1][i] = p[l][i];
                end
            end
        end
    endgenerate
    // carry into operand bit i = the group generate of positions [0, i]
    assign s = (a ^ b) ^ g[L][W-1:0];
    assign cout = g[L][W];
endmodule


module ref_ot_v41_inc #(
    parameter integer W = 24
) (
    input  wire [W-1:0] a,
    input  wire         inc,
    output wire [W-1:0] y,
    output wire         co
);
    localparam integer L = $clog2(W + 1);
    // t[i]: all of positions [0, i] are one, position 0 being the increment
    (* keep *) wire [W:0] t [0:L];
    assign t[0] = {a, inc};
    genvar l, i;
    generate
        for (l = 0; l < L; l = l + 1) begin : g_lv
            for (i = 0; i <= W; i = i + 1) begin : g_b
                if (i >= (1 << l)) begin : g_c
                    assign t[l + 1][i] = t[l][i] & t[l][i - (1 << l)];
                end else begin : g_p
                    assign t[l + 1][i] = t[l][i];
                end
            end
        end
    endgenerate
    assign y = a ^ t[L][W-1:0];
    assign co = t[L][W];
endmodule

files.ref_ot_hdc_cg.sv:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// ot_hdc_cg: integrated clock gate for unit-level clock gating.
//
// Not instantiated by any block.  Gating of the as-built decode-core blocks was
// withdrawn on 2026-09-26 when the core was re-specified top-down; it is to be
// re-applied to the final blocks.  With it the Qwen and V4.1 decode campaigns
// stayed bit-exact and cycle-identical, and the routed V4.1 units closed with
// tools/run_abi3_physical.py --clock-gating except the activation quantiser,
// whose s0 -> s1 max tree missed 0.9 ns by 14-47 ps across two routes (the cause
// was not attributed before the stop; it was NOT the input-register enable).
//
// Function: gclk follows clk while en was high at the clock's last low phase,
// and stays low otherwise, so a gated register sees exactly the rising edges
// at which en was 1 -- the same edges at which an enabled register would load.
// Synthesis maps it onto the platform's latch-based ICG cell; the model below
// is that cell's function (a latch transparent while clk is low, ANDed with
// clk), so simulation clocks the gated registers exactly as the cell will.
// The instance keeps the name u_icg: tools/signoff_analysis.py annotates the
// cell's ENA pin from this module's `en`.  Every user must OR !rst_n into
// `en`: the reset is asynchronous in silicon, but a simulator that starts with
// rst_n already low sees no negedge and applies it only on clock edges, so the
// gated registers must be clocked during reset.
// ---------------------------------------------------------------------------
module ref_ot_hdc_cg (
    input  wire clk,
    input  wire en /*verilator clock_enable*/,
    output wire gclk
);
`ifdef SYNTHESIS
    ICGx1_ASAP7_75t_R u_icg (.CLK(clk), .ENA(en), .SE(1'b0), .GCLK(gclk));
`else
    reg en_l;
    /* verilator lint_off COMBDLY */
    always_latch if (!clk) en_l = en;   // transparent while clk is low
    /* verilator lint_on COMBDLY */
    assign gclk = clk & en_l;
`endif
endmodule

files.ref_ot_hdc_delay.sv:
`timescale 1ns/1ps
// Fixed delay line: q is d delayed by D cycles (D = 0 is a wire).  Data lines
// carry no reset -- validity travels on a separate, reset delay line -- so a
// wide operand costs flops and no reset fan-out.
module ref_ot_hdc_delay #(
    parameter integer W = 32,
    parameter integer D = 1,
    parameter integer RESET = 0
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [W-1:0] d,
    output wire [W-1:0] q
);
    generate
        if (D == 0) begin : g_wire
            assign q = d;
        end else if (D == 1) begin : g_one
            reg [W-1:0] line;
            if (RESET != 0) begin : g_rst
                always @(posedge clk or negedge rst_n)
                    if (!rst_n) line <= {W{1'b0}};
                    else line <= d;
            end else begin : g_nrst
                always @(posedge clk) line <= d;
            end
            assign q = line;
        end else begin : g_line
            reg [W*D-1:0] line;
            if (RESET != 0) begin : g_rst
                always @(posedge clk or negedge rst_n)
                    if (!rst_n) line <= {(W*D){1'b0}};
                    else line <= {line[W*(D-1)-1:0], d};
            end else begin : g_nrst
                always @(posedge clk) line <= {line[W*(D-1)-1:0], d};
            end
            assign q = line[W*D-1 -: W];
        end
    endgenerate
endmodule

files.ref_ot_hdc_fp32_mul_pipe.sv:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// Rebalanced copy of rtl/proto/ot_fp32_mul_rne_pipe.sv for the decode core.
//
// Routed inside the core's special-function units, the qualified pipe closes
// at 950-990 MHz on ASAP7, and the path is always its stage 2: the whole
// 24x24 significand multiply in one cycle, while stage 3 holds only a few
// 12-bit exponent adds.  This copy moves work across that boundary without
// changing a result bit:
//
//   stage 2  three 24x8 partial products (b split into bytes), and BOTH
//            candidate exponent/alignment decisions (leading bit 47 or 46),
//            which depend only on the exponents;
//   stage 3  the three-term sum of the partial products and a 2:1 select of
//            the precomputed decision by the product's top bit.
//
// Same latency (5), same interface, same semantics, bit for bit -- checked
// against the qualified pipe by tools/rtl_hdc_mul_equivalence.py.
// ---------------------------------------------------------------------------
module ref_ot_hdc_fp32_mul_pipe (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_in,
    input  wire [31:0] a,
    input  wire [31:0] b,
    output reg  [31:0] y,
    output reg  [1:0]  err,
    output reg         valid_out
);
    localparam [1:0] E_NONE = 2'd0;
    localparam [1:0] E_NONFINITE = 2'd1;
    localparam [1:0] E_OVERFLOW = 2'd2;

    integer k;

    // -- stage 1: decode, normalize subnormals, resolve zero and nonfinite ----
    wire [7:0]  a_field = a[30:23];
    wire [7:0]  b_field = b[30:23];
    wire [23:0] a_raw = {(a_field != 8'd0), a[22:0]};
    wire [23:0] b_raw = {(b_field != 8'd0), b[22:0]};
    wire        s1_nonfinite = (a_field == 8'hff) || (b_field == 8'hff);
    wire        s1_zero = (a_raw == 24'd0) || (b_raw == 24'd0);

    //: A subnormal is shifted up until bit 23 is set, its exponent following it
    //: down -- exactly the authority's 23-iteration loop, as one shift.
    function automatic [4:0] lead_shift_24;
        input [23:0] value;
        reg [4:0] shift;
        integer bit_index;
        begin
            shift = 5'd23;
            for (bit_index = 0; bit_index <= 23; bit_index = bit_index + 1)
                if (value[bit_index]) shift = 5'd23 - bit_index[4:0];
            lead_shift_24 = shift;
        end
    endfunction
    wire [4:0] a_shift = lead_shift_24(a_raw);
    wire [4:0] b_shift = lead_shift_24(b_raw);
    //: The authority's powers: field - 150 for a normal, -149 for a subnormal,
    //: then one less for every normalizing shift.
    wire signed [11:0] a_power = (a_field == 8'd0)
        ? (-12'sd149 - {7'd0, a_shift})
        : ($signed({4'd0, a_field}) - 12'sd150);
    wire signed [11:0] b_power = (b_field == 8'd0)
        ? (-12'sd149 - {7'd0, b_shift})
        : ($signed({4'd0, b_field}) - 12'sd150);

    reg        s1_v, s1_byp;
    reg [1:0]  s1_err;
    reg        s1_sign;
    reg [23:0] s1_a, s1_b;
    reg signed [11:0] s1_power;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s1_v <= 1'b0; s1_byp <= 1'b0; s1_err <= E_NONE; s1_sign <= 1'b0;
            s1_a <= 24'd0; s1_b <= 24'd0; s1_power <= 12'sd0;
        end else begin
            s1_v <= valid_in;
            s1_byp <= s1_nonfinite || s1_zero;
            s1_err <= s1_nonfinite ? E_NONFINITE : E_NONE;
            s1_sign <= a[31] ^ b[31];
            s1_a <= a_raw << a_shift;
            s1_b <= b_raw << b_shift;
            s1_power <= a_power + b_power;
        end
    end

    // -- stage 2: three 24x8 partial products; both exponent decisions ---------
    //: 46 or 47, never anything else, because both significands carry bit 23;
    //: the decision for each case needs only the exponents, so both are ready
    //: before the product is.
    function automatic [24:0] decide;     // {is_sub, floor[11:0], shift[11:0]}
        input signed [11:0] power;
        input [5:0] msb;
        reg signed [11:0] fl, sh;
        reg sub;
        begin
            fl = power + $signed({6'd0, msb});
            sub = (fl < -12'sd126);
            //: The normal-result align, and the subnormal-result align in units
            //: of the binary32 subnormal LSB; the authority picks on floor >= -126.
            sh = sub ? -(power + 12'sd149) : ($signed({6'd0, msb}) - 12'sd23);
            decide = {sub, fl, sh};
        end
    endfunction

    reg        s2_v, s2_byp, s2_sign;
    reg [1:0]  s2_err;
    reg [31:0] s2_pp0, s2_pp1, s2_pp2;
    reg [24:0] s2_d47, s2_d46;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s2_v <= 1'b0; s2_byp <= 1'b0; s2_sign <= 1'b0; s2_err <= E_NONE;
            s2_pp0 <= 32'd0; s2_pp1 <= 32'd0; s2_pp2 <= 32'd0; s2_d47 <= 25'd0; s2_d46 <= 25'd0;
        end else begin
            s2_v <= s1_v; s2_byp <= s1_byp; s2_sign <= s1_sign; s2_err <= s1_err;
            s2_pp0 <= {8'd0, s1_a} * {24'd0, s1_b[7:0]};
            s2_pp1 <= {8'd0, s1_a} * {24'd0, s1_b[15:8]};
            s2_pp2 <= {8'd0, s1_a} * {24'd0, s1_b[23:16]};
            s2_d47 <= decide(s1_power, 6'd47);
            s2_d46 <= decide(s1_power, 6'd46);
        end
    end

    // -- stage 3: the product, and the decision its top bit selects -----------
    wire [47:0] s3_prod = {16'd0, s2_pp0} + {8'd0, s2_pp1, 8'd0} + {s2_pp2, 16'd0};
    wire [24:0] s3_dec = s3_prod[47] ? s2_d47 : s2_d46;

    reg        s3_v, s3_byp, s3_sign, s3_is_sub_q;
    reg [1:0]  s3_err;
    reg [47:0] s3_product;
    reg signed [11:0] s3_floor_q, s3_shift_q;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s3_v <= 1'b0; s3_byp <= 1'b0; s3_sign <= 1'b0; s3_is_sub_q <= 1'b0;
            s3_err <= E_NONE; s3_product <= 48'd0;
            s3_floor_q <= 12'sd0; s3_shift_q <= 12'sd0;
        end else begin
            s3_v <= s2_v; s3_byp <= s2_byp; s3_sign <= s2_sign;
            s3_err <= s2_err; s3_product <= s3_prod;
            s3_is_sub_q <= s3_dec[24];
            s3_floor_q <= s3_dec[23:12];
            s3_shift_q <= s3_dec[11:0];
        end
    end

    // -- stage 4: align, extract round and sticky, round to nearest even ------
    //: The authority's shift_right_48_to_24: bits outside the product are zero,
    //: so a distance at or past 48 leaves nothing.
    function automatic [23:0] shift_48_to_24;
        input [47:0] value;
        input signed [11:0] distance;
        reg [23:0] taken;
        reg signed [11:0] source;
        integer bit_index;
        begin
            taken = 24'd0;
            for (bit_index = 0; bit_index < 24; bit_index = bit_index + 1) begin
                source = $signed({4'd0, bit_index[7:0]}) + distance;
                //: Narrowed to the product's own index width only where the
                //: guard has already put it in range.
                if ((source >= 12'sd0) && (source < 12'sd48))
                    taken[bit_index] = value[source[5:0]];
            end
            shift_48_to_24 = taken;
        end
    endfunction
    //: ``sticky`` is every bit strictly below the round bit.
    function automatic sticky_below;
        input [47:0] value;
        input signed [11:0] distance;
        reg found;
        integer bit_index;
        begin
            found = 1'b0;
            for (bit_index = 0; bit_index < 48; bit_index = bit_index + 1)
                if ($signed({4'd0, bit_index[7:0]}) < distance - 12'sd1)
                    found = found | value[bit_index];
            sticky_below = found;
        end
    endfunction

    wire [23:0] s4_main = (s3_is_sub_q && (s3_shift_q >= 12'sd48))
                        ? 24'd0
                        : shift_48_to_24(s3_product, s3_shift_q);
    //: Named so the index is narrowed once, inside the range the guard proves.
    wire signed [11:0] s4_round_index = s3_shift_q - 12'sd1;
    wire s4_round_in_range = (s3_shift_q > 12'sd0) && (s3_shift_q <= 12'sd48);
    wire s4_round_bit = s4_round_in_range &&
                        s3_product[s4_round_in_range ? s4_round_index[5:0]
                                                     : 6'd0];
    wire s4_sticky = sticky_below(s3_product, s3_shift_q);
    wire [24:0] s4_rounded =
        {1'b0, s4_main} +
        {24'd0, (s4_round_bit && (s4_sticky || s4_main[0]))};

    reg        s4_v, s4_byp, s4_sign, s4_is_sub;
    reg [1:0]  s4_err;
    reg [24:0] s4_mant;
    reg signed [11:0] s4_floor;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s4_v <= 1'b0; s4_byp <= 1'b0; s4_sign <= 1'b0; s4_is_sub <= 1'b0;
            s4_err <= E_NONE; s4_mant <= 25'd0; s4_floor <= 12'sd0;
        end else begin
            s4_v <= s3_v; s4_byp <= s3_byp; s4_sign <= s3_sign;
            s4_err <= s3_err; s4_is_sub <= s3_is_sub_q;
            s4_mant <= s4_rounded;
            s4_floor <= s3_floor_q;
        end
    end

    // -- stage 5: the post-round carry, the encoding, and the refusals --------
    //: A carry out of bit 24 moves the leading bit up one exponent.
    wire        s5_carry = !s4_is_sub && s4_mant[24];
    wire [23:0] s5_man = s5_carry ? s4_mant[24:1] : s4_mant[23:0];
    wire signed [11:0] s5_floor = s4_floor + $signed({11'd0, s5_carry});
    wire        s5_over = !s4_is_sub && (s5_floor > 12'sd127);
    wire [7:0]  s5_field = s5_floor[7:0] + 8'd127;
    //: The subnormal path rounds in LSB units, so a mantissa reaching 2**23 has
    //: rounded UP into the smallest normal and is encoded with field 1.
    wire        s5_sub_carry = s4_is_sub && (s4_mant >= 25'h080_0000);
    wire [31:0] s5_code =
        s4_is_sub ? (s5_sub_carry ? {s4_sign, 8'h01, 23'd0}
                                  : {s4_sign, 8'h00, s4_mant[22:0]})
                  : {s4_sign, s5_field, s5_man[22:0]};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            y <= 32'd0; err <= E_NONE; valid_out <= 1'b0;
        end else begin
            valid_out <= s4_v;
            if (s4_byp) begin
                //: A zero operand gives +0 whatever the signs; nonfinite gives
                //: the refusal and a zero code, never an infinity.
                y <= 32'd0;
                err <= s4_err;
            end else if (s5_over) begin
                y <= 32'd0;
                err <= E_OVERFLOW;
            end else begin
                y <= (s5_code[30:0] == 31'd0) ? 32'd0 : s5_code;
                err <= E_NONE;
            end
        end
    end
endmodule

files.ref_ot_hdc_fpu.sv:
`timescale 1ns/1ps
// Thin wrappers over the binary32 pipes: one result per cycle, LATENCY = 5,
// IEEE RNE with gradual underflow and canonical +0 zeros.  The adder is the
// qualified rtl/proto pipe; the multiplier is its stage-rebalanced copy
// ot_hdc_fp32_mul_pipe (1,275 vs 1,052 MHz routed alone on ASAP7), proven
// cycle-equivalent by rtl/test/tb_hdc_mul_equiv.sv.
// A nonfinite operand or an overflow raises `fault` on a valid result; the
// decode core ORs every fault into one sticky status bit.
module ref_ot_hdc_fadd (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] a,
    input  wire [31:0] b,
    output wire [31:0] y,
    output wire        fault
);
    wire [1:0] err;
    wire vo;
    ref_ot_fp32_add_rne_pipe u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b),
                            .y(y), .err(err), .valid_out(vo));
    assign fault = vo && (err != 2'd0);
endmodule

module ref_ot_hdc_fmul (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] a,
    input  wire [31:0] b,
    output wire [31:0] y,
    output wire        fault
);
    wire [1:0] err;
    wire vo;
    ref_ot_hdc_fp32_mul_pipe u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b),
                            .y(y), .err(err), .valid_out(vo));
    assign fault = vo && (err != 2'd0);
endmodule

// BF16 x BF16 -> FP32 multiply, exact.  Two 8-bit significands give at most 16
// significant bits, so the binary32 product needs no rounding whenever it is
// normal, or subnormal by at most 7 bits of shift; there it is bit-identical
// to ot_fp32_mul_rne_pipe on the same operands (RN of an exact value is that
// value).  Operands arrive as binary32 words whose low 16 bits are ignored.
// A zero operand gives +0.  A product too small to be exact, an overflow or a
// nonfinite operand FAILS CLOSED through `fault` (and y = +0) -- the qualified
// pipe would round or refuse there.  LATENCY 5, like the FP32 pipe, so a
// lane's schedule does not depend on which multiplier it has.
module ref_ot_hdc_bmul (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] a,
    input  wire [31:0] b,
    output reg  [31:0] y,
    output reg         fault
);
    // stage 1: decode; a subnormal significand is normalised by its top bit
    function automatic [17:0] dec;   // {sig[7:0], E[9:0] signed}
        input [7:0] e;
        input [6:0] m;
        integer i;
        reg [2:0] p;
        begin
            if (e != 0) dec = {1'b1, m, e - 10'sd127};
            else begin
                p = 0;
                for (i = 0; i < 7; i = i + 1) if (m[i]) p = i[2:0];
                dec = {({1'b0, m} << (7 - p)), $signed(-10'sd133) + $signed({7'd0, p})};
            end
        end
    endfunction
    wire [17:0] da = dec(a[30:23], a[22:16]);
    wire [17:0] db = dec(b[30:23], b[22:16]);
    reg        s1_v, s1_s, s1_z, s1_nf;
    reg [7:0]  s1_a, s1_b;
    reg signed [10:0] s1_e;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s1_v <= 1'b0;
        else s1_v <= v;
    end
    always @(posedge clk) begin
        s1_s <= a[31] ^ b[31];
        s1_z <= (a[30:16] == 15'd0) || (b[30:16] == 15'd0);
        s1_nf <= (a[30:23] == 8'hFF) || (b[30:23] == 8'hFF);
        s1_a <= da[17:10]; s1_b <= db[17:10];
        s1_e <= $signed(da[9:0]) + $signed(db[9:0]);
    end
    // stage 2: the 8x8 product
    reg        s2_v, s2_s, s2_z, s2_nf;
    reg [15:0] s2_p;
    reg signed [10:0] s2_e;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s2_v <= 1'b0;
        else s2_v <= s1_v;
    end
    always @(posedge clk) begin
        s2_s <= s1_s; s2_z <= s1_z; s2_nf <= s1_nf; s2_e <= s1_e;
        s2_p <= s1_a * s1_b;
    end
    // stage 3: normalise (leading bit 15 or 14) and bias
    reg        s3_v, s3_s, s3_z, s3_nf;
    reg [22:0] s3_f;
    reg signed [10:0] s3_be;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s3_v <= 1'b0;
        else s3_v <= s2_v;
    end
    always @(posedge clk) begin
        s3_s <= s2_s; s3_z <= s2_z; s3_nf <= s2_nf;
        if (s2_p[15]) begin s3_f <= {s2_p[14:0], 8'd0}; s3_be <= s2_e + 11'sd128; end
        else          begin s3_f <= {s2_p[13:0], 9'd0}; s3_be <= s2_e + 11'sd127; end
    end
    // stage 4: encode; a subnormal result shifts right by 1 - biased (<= 7)
    reg        s4_v, s4_bad;
    reg [31:0] s4_y;
    wire [23:0] sig24 = {1'b1, s3_f};
    wire [3:0]  sub_sh = 4'd1 - s3_be[3:0];
    wire [23:0] sub_v = sig24 >> sub_sh;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s4_v <= 1'b0;
        else s4_v <= s3_v;
    end
    always @(posedge clk) begin
        s4_bad <= 1'b0;
        if (s3_z && !s3_nf) s4_y <= 32'd0;
        else if (s3_nf || s3_be > 11'sd254 || s3_be < -11'sd6) begin s4_y <= 32'd0; s4_bad <= 1'b1; end
        else if (s3_be >= 11'sd1) s4_y <= {s3_s, s3_be[7:0], s3_f};
        else s4_y <= {s3_s, 8'd0, sub_v[22:0]};
    end
    // stage 5: output register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin y <= 32'd0; fault <= 1'b0; end
        else begin y <= s4_y; fault <= s4_v && s4_bad; end
    end
endmodule

files.ref_ot_fp32_add_rne_pipe.sv:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// Pipelined binary32 adder, one result per cycle.
//
// This is the arithmetic ``ot_fp32_rne_pkg::fp32_add_rne`` performs
// COMBINATIONALLY.  That function is the project's scalar authority and stays
// so; what it is not is fast.  Placed inside ot_a3_reduction_expert_sum it set
// the whole engine's clock at 157.6 MHz, because decode, a 28-bit jamming
// align, the add, a 27-bit normalizing shift and the round all sit in one cone.
// Cut into five stages the same cone closes an order of magnitude higher, and
// the engines that need binary32 addition stop paying for it.
//
// WHY THE ENGINES CANNOT USE THE MAC INSTEAD.  ot_mac_bf16_fp32_pipe computes
// RN(a*b + c) at II=1 with a BF16 ``a`` and an FP32 ``c``, so ``b = BF16 1.0``
// turns it into an adder -- but only when one addend is BF16.  Every shipped
// ROUTE.WEIGHT_NORMALIZE is FP32-in/FP32-out, and ROUTE.EXPERT_SUM accumulates
// FP32, so both need two FP32 addends and neither fits.
//
// A SEQUENTIAL FOLD DOES NOT GET FASTER BY BEING PIPELINED -- acc = acc + w is
// loop-carried, so one group still costs LATENCY cycles per term.  What
// pipelining buys is the clock, and the right to interleave INDEPENDENT
// reductions (WEIGHT_NORMALIZE ships 262,144 groups) through the same adder at
// one per cycle.  Callers that fold a single long chain should expect
// LATENCY-cycle spacing and schedule other work into the gaps.
//
// BIT-IDENTICAL TO THE AUTHORITY, INCLUDING WHERE THE AUTHORITY IS NOT IEEE.
// Two behaviours here are deliberately not what a fresh IEEE implementation
// would do, and are reproduced because the authority is the contract:
//
//   * (-0) + (-0) is +0.  The authority takes the ``left_mantissa == 0`` branch,
//     sees a zero right operand and returns a literal 32'b0.  IEEE-754 says -0.
//   * every zero result is canonical +0, from the closing
//     ``if (result[30:0] == 0) result = 0``.
//
// A nonfinite operand and a result that rounds past the finite range FAIL
// CLOSED through ``err``; they are never encoded as an infinity.
// ---------------------------------------------------------------------------
module ref_ot_fp32_add_rne_pipe (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_in,
    input  wire [31:0] a,
    input  wire [31:0] b,
    output reg  [31:0] y,
    output reg  [1:0]  err,
    output reg         valid_out
);
    localparam [1:0] E_NONE = 2'd0;
    localparam [1:0] E_NONFINITE = 2'd1;
    localparam [1:0] E_OVERFLOW = 2'd2;

    integer k;

    // -- stage 1: decode, order by magnitude, resolve the zero operands ------
    wire        a_sign = a[31];
    wire        b_sign = b[31];
    wire [7:0]  a_field = a[30:23];
    wire [7:0]  b_field = b[30:23];
    //: A zero exponent field means subnormal: exponent 1, no implicit leading
    //: one. The authority does exactly this, so a subnormal operand is a genuine
    //: subnormal here and not a flushed zero.
    wire [7:0]  a_exp = (a_field == 8'd0) ? 8'd1 : a_field;
    wire [7:0]  b_exp = (b_field == 8'd0) ? 8'd1 : b_field;
    wire [23:0] a_man = {(a_field != 8'd0), a[22:0]};
    wire [23:0] b_man = {(b_field != 8'd0), b[22:0]};

    wire s1_nonfinite = (a_field == 8'hff) || (b_field == 8'hff);
    wire a_is_zero = (a_man == 24'd0);
    wire b_is_zero = (b_man == 24'd0);
    //: The authority's own order: left-zero first, so (+-0) + (+-0) is +0 and
    //: not the IEEE -0 that a symmetric implementation would produce.
    wire s1_bypass = s1_nonfinite || a_is_zero || b_is_zero;
    wire [31:0] s1_bypass_code =
        s1_nonfinite ? 32'd0
                     : (a_is_zero ? (b_is_zero ? 32'd0 : b)
                                  : a);

    //: |b| > |a| decides the swap; on equal magnitude the left operand stays
    //: large, which is what fixes the result sign for a cancelling pair.
    wire swap = (b_exp > a_exp) || ((b_exp == a_exp) && (b_man > a_man));
    wire [7:0]  big_exp = swap ? b_exp : a_exp;
    wire [7:0]  small_exp = swap ? a_exp : b_exp;
    wire [23:0] big_man = swap ? b_man : a_man;
    wire [23:0] small_man = swap ? a_man : b_man;

    reg        s1_v, s1_byp, s1_sub, s1_sign;
    reg [1:0]  s1_err;
    reg [31:0] s1_code;
    reg [7:0]  s1_exp, s1_dist;
    reg [23:0] s1_big, s1_small;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s1_v <= 1'b0; s1_byp <= 1'b0; s1_sub <= 1'b0; s1_sign <= 1'b0;
            s1_err <= E_NONE; s1_code <= 32'd0; s1_exp <= 8'd0;
            s1_dist <= 8'd0; s1_big <= 24'd0; s1_small <= 24'd0;
        end else begin
            s1_v <= valid_in;
            s1_byp <= s1_bypass;
            s1_err <= s1_nonfinite ? E_NONFINITE : E_NONE;
            s1_code <= s1_bypass_code;
            s1_sub <= (a_sign != b_sign);
            s1_sign <= swap ? b_sign : a_sign;
            s1_exp <= big_exp;
            //: Both fields are 8 bits and big >= small, so the difference cannot
            //: borrow; the jam shifter saturates it past 28 on its own.
            s1_dist <= big_exp - small_exp;
            s1_big <= big_man;
            s1_small <= small_man;
        end
    end

    // -- stage 2: align the smaller significand, jamming what falls off ------
    //: Three guard bits below the significand, and everything shifted out is
    //: OR-ed into the lowest of them. Without that sticky a cancellation moves a
    //: dropped bit into the round position and the last bit comes out wrong.
    function automatic [27:0] shift_right_jam_28;
        input [27:0] value;
        input [7:0]  distance;
        reg discarded;
        reg [27:0] shifted;
        integer bit_index;
        begin
            discarded = 1'b0;
            shifted = 28'd0;
            if (distance == 8'd0) begin
                shifted = value;
            end else if (distance >= 8'd28) begin
                shifted[0] = |value;
            end else begin
                shifted = value >> distance;
                for (bit_index = 0; bit_index < 28; bit_index = bit_index + 1)
                    if ({24'd0, bit_index[7:0]} < distance)
                        discarded = discarded | value[bit_index];
                shifted[0] = shifted[0] | discarded;
            end
            shift_right_jam_28 = shifted;
        end
    endfunction

    reg        s2_v, s2_byp, s2_sub, s2_sign;
    reg [1:0]  s2_err;
    reg [31:0] s2_code;
    reg [7:0]  s2_exp;
    reg [27:0] s2_big, s2_small;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s2_v <= 1'b0; s2_byp <= 1'b0; s2_sub <= 1'b0; s2_sign <= 1'b0;
            s2_err <= E_NONE; s2_code <= 32'd0; s2_exp <= 8'd0;
            s2_big <= 28'd0; s2_small <= 28'd0;
        end else begin
            s2_v <= s1_v; s2_byp <= s1_byp; s2_sub <= s1_sub;
            s2_sign <= s1_sign; s2_err <= s1_err; s2_code <= s1_code;
            s2_exp <= s1_exp;
            s2_big <= {1'b0, s1_big, 3'b000};
            s2_small <= shift_right_jam_28({1'b0, s1_small, 3'b000}, s1_dist);
        end
    end

    // -- stage 3: the add or subtract, and the add's single-bit renormalize --
    wire [27:0] s3_sum = s2_big + s2_small;
    wire [27:0] s3_dif = s2_big - s2_small;
    wire [27:0] s3_arith = s2_sub ? s3_dif : s3_sum;
    //: A carry out of bit 27 shifts one right and keeps the lost bit sticky.
    wire        s3_carry = !s2_sub && s3_sum[27];
    //: Written out rather than as a part-select of a part-select: Verilator
    //: accepts that form and the pinned Yosys 0.68 frontend rejects it.
    wire [26:0] s3_shifted = {s3_sum[27:2], s3_sum[1] | s3_sum[0]};

    reg        s3_v, s3_byp, s3_sub, s3_sign, s3_zero;
    reg [1:0]  s3_err;
    reg [31:0] s3_code;
    reg [7:0]  s3_exp;
    reg [26:0] s3_val;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s3_v <= 1'b0; s3_byp <= 1'b0; s3_sub <= 1'b0; s3_sign <= 1'b0;
            s3_zero <= 1'b0; s3_err <= E_NONE; s3_code <= 32'd0;
            s3_exp <= 8'd0; s3_val <= 27'd0;
        end else begin
            s3_v <= s2_v; s3_byp <= s2_byp; s3_sub <= s2_sub;
            s3_sign <= s2_sign; s3_err <= s2_err; s3_code <= s2_code;
            //: An exactly cancelling subtraction is +0 and skips the rest.
            s3_zero <= s2_sub && (s3_dif == 28'd0);
            s3_exp <= s3_carry ? (s2_exp + 8'd1) : s2_exp;
            s3_val <= s3_carry ? s3_shifted : s3_arith[26:0];
        end
    end

    // -- stage 4: the cancellation normalize --------------------------------
    //: The authority shifts left one bit at a time while bit 26 is clear AND the
    //: exponent is above 1, at most 27 times. So the shift is the leading-zero
    //: count CLAMPED BY THE EXPONENT FLOOR -- a large cancellation near the
    //: bottom of the range stops at exponent 1 and stays subnormal rather than
    //: normalizing into an exponent it cannot encode.
    reg [4:0] s4_lz;
    always @* begin
        s4_lz = 5'd27;
        //: ASCENDING, so the LAST assignment is the HIGHEST set bit. Counting
        //: down leaves the lowest set bit instead, which normalizes a cancelling
        //: subtraction by far too much and is wrong on every case that cancels.
        for (k = 0; k <= 26; k = k + 1)
            if (s3_val[k]) s4_lz = 5'd26 - k[4:0];
    end
    wire [7:0] s4_room = s3_exp - 8'd1;
    wire [7:0] s4_shift = ({3'd0, s4_lz} > s4_room) ? s4_room : {3'd0, s4_lz};
    wire       s4_apply = s3_sub && !s3_zero && !s3_byp;

    reg        s4_v, s4_byp, s4_sign, s4_zero;
    reg [1:0]  s4_err;
    reg [31:0] s4_code;
    reg [7:0]  s4_exp;
    reg [26:0] s4_val;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s4_v <= 1'b0; s4_byp <= 1'b0; s4_sign <= 1'b0; s4_zero <= 1'b0;
            s4_err <= E_NONE; s4_code <= 32'd0; s4_exp <= 8'd0; s4_val <= 27'd0;
        end else begin
            s4_v <= s3_v; s4_byp <= s3_byp; s4_sign <= s3_sign;
            s4_zero <= s3_zero; s4_err <= s3_err; s4_code <= s3_code;
            s4_exp <= s4_apply ? (s3_exp - s4_shift) : s3_exp;
            s4_val <= s4_apply ? (s3_val << s4_shift) : s3_val;
        end
    end

    // -- stage 5: round to nearest even, encode, fail closed on overflow -----
    wire [24:0] s5_trunc = {1'b0, s4_val[26:3]};
    //: Ties to EVEN: increment on the round bit only when something below it is
    //: set or the retained bit is already odd.
    wire        s5_inc = s4_val[2] && ((|s4_val[1:0]) || s4_val[3]);
    wire [24:0] s5_round = s5_trunc + {24'd0, s5_inc};
    wire        s5_carry = s5_round[24];
    wire [23:0] s5_man = s5_carry ? s5_round[24:1] : s5_round[23:0];
    wire [7:0]  s5_exp = s5_carry ? (s4_exp + 8'd1) : s4_exp;
    //: Exponent 1 with no leading one left is the subnormal encoding: field 0.
    wire        s5_subnormal = (s5_exp == 8'd1) && !s5_man[23];
    wire [31:0] s5_code = {s4_sign, s5_subnormal ? 8'd0 : s5_exp, s5_man[22:0]};
    //: Overflow before rounding and after it are both refusals, never infinity.
    wire        s5_over = (s4_exp >= 8'hff) || (s5_exp >= 8'hff);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            y <= 32'd0; err <= E_NONE; valid_out <= 1'b0;
        end else begin
            valid_out <= s4_v;
            if (s4_byp) begin
                y <= s4_code;
                err <= s4_err;
            end else if (s4_zero) begin
                y <= 32'd0;
                err <= E_NONE;
            end else if (s5_over) begin
                y <= 32'd0;
                err <= E_OVERFLOW;
            end else begin
                //: The authority's closing canonicalization: any zero is +0.
                y <= (s5_code[30:0] == 31'd0) ? 32'd0 : s5_code;
                err <= E_NONE;
            end
        end
    end
endmodule

files.ref_ot_rom_4096x274_m8_rt.sv:
`timescale 1ns/1ps
// Simulation-only PP adapter. Host images stay logical 8192-word banks.
// The element owns the PP capture registers; this macro retains one-edge read/hold.
module ref_ot_rom_4096x274_m8 #(parameter string VIAMAP = "", parameter string INSTANCE = "") (
    input wire clk,
    input wire ce_in,
    input wire [11:0] addr_in,
    output reg [273:0] rd_out
);
    import "DPI-C" context function void v41rt_rom_register(input string inst);
    import "DPI-C" context function void v41rt_rom_read(input int addr, output bit [273:0] q);
    string logical_instance;
    integer parity;
    bit [273:0] w;
    initial begin
        if (INSTANCE.len() < 2 || INSTANCE[INSTANCE.len()-2] != "_" ||
            (INSTANCE[INSTANCE.len()-1] != "0" && INSTANCE[INSTANCE.len()-1] != "1"))
            $fatal(1, "PP INSTANCE must end in _0 or _1");
        parity = (INSTANCE[INSTANCE.len()-1] == "1");
        logical_instance = INSTANCE.len() == 2 ? "" : INSTANCE.substr(0, INSTANCE.len()-3);
        v41rt_rom_register(logical_instance);
    end
    always @(posedge clk)
        if (ce_in) begin
            v41rt_rom_read(2 * int'(addr_in) + parity, w);
            rd_out <= w;
        end
endmodule

files.ref_ot_rom_8192x274_m8_rt.sv:
`timescale 1ns/1ps
// SIMULATION ONLY (W17 runtime composition, tools/v41_field_rt_gate.py): the ROM macro ot_rom_8192x274_m8 with
// the same port behaviour as the via-programmed model (a read on ce_in returns the addressed 274-bit word at the
// next edge; the output holds when ce_in is low) but its words served by the runtime host through DPI, so one
// compiled element model serves every element of the field.  The host keys each macro by the calling scope,
// registered once at time 0 with the macro's INSTANCE suffix ("" = the pair's first macro, "b" = the second).
module ref_ot_rom_8192x274_m8 #(parameter string VIAMAP = "", parameter string INSTANCE = "") (
    input  wire clk,
    input  wire ce_in,
    input  wire [12:0] addr_in,
    output reg  [273:0] rd_out
);
    import "DPI-C" context function void v41rt_rom_register(input string inst);
    import "DPI-C" context function void v41rt_rom_read(input int addr, output bit [273:0] q);
    initial v41rt_rom_register(INSTANCE);
    bit [273:0] w;
    always @(posedge clk)
        if (ce_in) begin
            v41rt_rom_read({19'd0, addr_in}, w);
            rd_out <= w;
        end
endmodule

files.ref_ot_v41_pair_w17w10.sv:
// Experimental companion: FAST/PP/BP default off; no adoption or clock claim.
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// ot_v41_pair_w17w10: one ROM-field element of an experimental V4.1 FAST/PP runtime baseline (W17 die integration).
//
//   W10's ot_v41_rom_elem_w10 experimental baseline (NB = 2: a W1 macro pair sharing one front end, MTP,
//   fill cuts) + its per-element CONFIGURATION ROM and loader (root decision 2026-09-30 (b)).
//
// Configuration ROM.  Every phase the die runs has, for every element, the element's 3*NSEG+1 = 25
// configuration words (W10 ot_v41_rom_elem header: cfg_a 0..NSEG-1 segments, NSEG..2NSEG-1 classes,
// 2NSEG sub-blocks/positions, 2NSEG+1.. the second macro's rows), at entry ph*CW + a.  The spine
// broadcasts {cfg_go, cfg_ph}; every element then writes its CW words into its element on consecutive
// cycles (one ROM read a cycle, one register stage), in parallel across the field: a phase's
// configuration costs CW + 2 cycles regardless of the element count, and no configuration wire leaves
// the element.  The ROM is a mask ROM like the weights (tools/v41_die_images.py writes it).
//
// cfg_ph also carries the phase's positions - 1 (MTP) in the spine's broadcast; the ROM's word 2NSEG
// holds the sub-block count and the loader ORs the positions field in, so one ROM entry serves 1..6
// positions.
//
// Simulation: the ROM contents come from +OT_ROM_DIR=<dir>/<INSTANCE>.cfg.hex (flat builds) or, with V41_RT,
// are served by the runtime host through DPI (rtl/test/v41_runtime).
// ---------------------------------------------------------------------------
module ref_ot_v41_pair_w17w10 #(
    parameter integer NSEG = 8,
    parameter integer NCH = 16,
    parameter integer XF = 4,
    parameter integer LV = 5,
    parameter integer BF16 = 0,
    parameter integer MTP = 1,
    parameter integer EARLY = 1,
    parameter integer FAST = 0,
    parameter integer PP = 0,
    parameter integer BP = 0,
    parameter integer PHW = 6,          // phase id bits: 2^PHW phases per die
    parameter integer FIX_SECOND_ROW_INDEX = 0, // mandatory row decoder repair, opt-in preparation
    parameter integer WAKE_REG = 0, // retained true WAKE1 leaf join, off by default
    parameter integer GRADUAL_RNE = 0, // shared reviewed multiplier repair
    parameter INSTANCE = ""
) (
    input  wire         clk,
    input  wire         rst_n,
    // spine broadcast (after the broadcast wire stages)
    input  wire         cfg_go,
    input  wire [PHW-1:0] cfg_ph,
    input  wire [2:0]   cfg_np,         // positions - 1
    input  wire         go,
    input  wire         go_bf,
    input  wire         xs_v,
    input  wire [7:0]   xs_p,
    input  wire [2:0]   xs_b,
    input  wire [1:0]   xs_sv,
    input  wire [255:0] xs_q0,
    input  wire [9:0]   xs_e0,
    input  wire [255:0] xs_q1,
    input  wire [9:0]   xs_e1,
    input  wire [2:0]   xs_pos,
    input  wire [2:0]   xb_pos,
    input  wire         xb_v,
    input  wire [2:0]   xb_b,
    input  wire [3:0]   xb_sv,
    input  wire [31:0]  xb_u,
    input  wire [1023:0] xb_d,
    // the two macros' partials (return-tree leaves 2g, 2g + 1)
    output wire [1:0]   pv,
    output wire [63:0]  pval,
    output wire [31:0]  prow,
    output wire [9:0]   pseg,
    output wire [9:0]   pnseg,
    output wire [1:0]   perr,
    output wire [5:0]   ppos,
    output wire         busy,
    output wire         fault,
    // quiet: no op in flight, no partial pending, no configuration load (the element's clock is gated): clocking
    // a quiet pair changes nothing until cfg_go or go (simulation host uses it to skip evaluations)
    output wire         quiet
);
    localparam integer CW = 3 * NSEG + 1;
    localparam integer DEPTH = CW << PHW;
    localparam integer AW = $clog2(DEPTH);
    // the configuration mask ROM (48-bit words)
`ifdef V41_RT
    // runtime composition: the host serves the words (keyed by the calling scope, registered at time 0)
    import "DPI-C" context function void v41rt_cfg_register();
    import "DPI-C" context function longint v41rt_cfg_read(input int addr);
    initial v41rt_cfg_register();
    function automatic [47:0] cmr(input [AW-1:0] a);
        cmr = 48'(v41rt_cfg_read(32'(a)));
    endfunction
`else
    reg [47:0] cm [0:DEPTH-1];
    reg [8*1024-1:0] rom_dir;
    integer ii;
    initial begin
        for (ii = 0; ii < DEPTH; ii = ii + 1) cm[ii] = 48'd0;
        if ($value$plusargs("OT_ROM_DIR=%s", rom_dir) && INSTANCE != "")
            $readmemh({rom_dir, "/", INSTANCE, ".cfg.hex"}, cm);
    end
    function automatic [47:0] cmr(input [AW-1:0] a);
        cmr = cm[a];
    endfunction
`endif
    // loader: ROM address -> registered word -> element configuration port
    reg         ld_run;
    reg [4:0]   ld_k;
    reg [AW-1:0] ld_a;
    reg [2:0]   ld_np;
    reg         c_v;
    reg [4:0]   c_a;
    reg [47:0]  c_d;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ld_run <= 1'b0; ld_k <= 5'd0; c_v <= 1'b0;
        end else begin
            c_v <= ld_run;
            if (cfg_go) begin
                ld_run <= 1'b1; ld_k <= 5'd0;
                ld_a <= AW'(cfg_ph) * AW'(CW);
                ld_np <= cfg_np;
            end else if (ld_run) begin
                ld_k <= ld_k + 5'd1;
                ld_a <= ld_a + 1'b1;
                if (ld_k == 5'(CW - 1)) ld_run <= 1'b0;
            end
        end
    end
    // An element with no class in the phase gets no `go`: W10's element, started with an empty configuration,
    // walks stale state and corrupts its NEXT op (W17 gate, 2026-09-30; reported to W10).  The flag is the OR
    // of the phase's class-valid bits as they are loaded (no extra ROM bit).
    reg act;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) act <= 1'b0;
        else if (cfg_go) act <= 1'b0;
        else if (c_v && c_a >= 5'(NSEG) && c_a < 5'(2 * NSEG) && c_d[0]) act <= 1'b1;
    end
    wire go_e = go && act;
    always @(posedge clk) begin
        c_a <= ld_k;
