`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// ot_v41_bf16_lanes: the optional BF16 path of the V4.1 ROM-array element (W10; model: BF16 lanes on
// 2,048 of the busiest die's 13,798 macros).
//
// Golden mv / matvec_c under R-ARITH chunk8 (tools/hdc_golden_v41.py): products w * bf16(x) in binary32 (a
// BF16 x BF16 product is exact), each golden chunk of 8 consecutive products summed sequentially from +0,
// chunk sums combined by the padded pairwise tree.  A BF16 unit is a lane group of 16 consecutive golden
// chunks (128 elements); word b of a unit carries element b of each chunk (lane l <- chunk 16h + l), so
// each of the 16 lanes runs its own chunk chains (NCHB slots, one pipelined FP32 adder).  The 16 chunk sums
// of a unit complete in the same cycle and meet in a 15-adder, 4-level pairwise tree whose root is the
// golden level-4 node of that lane group; it leaves as one base node for the element's segment tree.
// Latency: product 5 (ot_hdc_bmul) + chain 5 + tree 20.
// ---------------------------------------------------------------------------
module ref_ot_v41_bf16_lanes #(
    parameter integer NCHB = 8,
    parameter integer TRW = 2          // tree-id width
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              v,
    input  wire [255:0]      w,        // 16 BF16 weights, lane l at [16l +: 16]
    input  wire [255:0]      x,        // 16 BF16 activations, lane l at [16l +: 16]
    input  wire [$clog2(NCHB)-1:0] slot,
    input  wire              first,
    input  wire              last,
    input  wire [TRW-1:0]    tree,
    input  wire              final_i,
    output wire              ov,
    output wire [31:0]       oval,
    output wire [TRW-1:0]    otree,
    output wire              ofinal,
    output wire              oerr,
    output wire              fault
);
    localparam integer HW = $clog2(NCHB);
    localparam integer TW = HW + 2 + TRW + 1;
    wire [TW-1:0] t_in = {slot, first, last, tree, final_i};
    wire [TW-1:0] t_p;
    ref_ot_hdc_delay #(.W(TW), .D(5)) u_pt (.clk(clk), .rst_n(rst_n), .d(t_in), .q(t_p));
    wire [15:0] pv;
    wire [15:0] pf;
    wire [31:0] prod [0:15];
    wire [15:0] cv, cf, cfault;
    wire [31:0] cs [0:15];
    wire [TRW:0] ct [0:15];
    genvar l;
    generate for (l = 0; l < 16; l = l + 1) begin : g_l
        ref_ot_hdc_bmul u_m (.clk(clk), .rst_n(rst_n), .v(v), .a({w[16*l +: 16], 16'd0}), .b({x[16*l +: 16], 16'd0}),
                         .y(prod[l]), .fault(pf[l]));
        reg [4:0] vp;
        always @(posedge clk or negedge rst_n) if (!rst_n) vp <= 5'd0; else vp <= {vp[3:0], v};
        assign pv[l] = vp[4];
        ref_ot_v41_chain #(.NCH(NCHB), .TW(TRW + 1)) u_c (.clk(clk), .rst_n(rst_n), .v(pv[l]),
            .slot(t_p[TW-1 -: HW]), .first(t_p[TRW+2]), .last(t_p[TRW+1]), .term(prod[l]), .term_f(pf[l]),
            .tag(t_p[TRW:0]), .ov(cv[l]), .osum(cs[l]), .of(cf[l]), .otag(ct[l]), .fault(cfault[l]));
    end endgenerate
    // 4-level pairwise tree over the 16 chunk sums (all lanes emit in the same cycle)
    wire [31:0] lvv [0:4][0:15];
    wire [15:0] lve [0:4];
    wire [4:0] lvvld;
    wire [TRW:0] lvt [0:4];
    generate for (l = 0; l < 16; l = l + 1) begin : g_in
        assign lvv[0][l] = cs[l];
        assign lve[0][l] = cf[l];
    end endgenerate
    assign lvvld[0] = cv[0];
    assign lvt[0] = ct[0];
    genvar lv, k;
    generate for (lv = 0; lv < 4; lv = lv + 1) begin : g_lv
        localparam integer NN = 16 >> (lv + 1);
        for (k = 0; k < NN; k = k + 1) begin : g_n
            wire [1:0] e;
            wire vo;
            ref_ot_fp32_add_rne_pipe u_a (.clk(clk), .rst_n(rst_n), .valid_in(lvvld[lv]), .a(lvv[lv][2*k]),
                                      .b(lvv[lv][2*k+1]), .y(lvv[lv+1][k]), .err(e), .valid_out(vo));
            reg [4:0] ep;
            always @(posedge clk) ep <= {ep[3:0], lve[lv][2*k] | lve[lv][2*k+1]};
            assign lve[lv+1][k] = ep[4] | (e != 2'd0);
        end
        for (k = NN; k < 16; k = k + 1) begin : g_z
            assign lvv[lv+1][k] = 32'd0;
            assign lve[lv+1][k] = 1'b0;
        end
        reg [4:0] vp;
        always @(posedge clk or negedge rst_n) if (!rst_n) vp <= 5'd0; else vp <= {vp[3:0], lvvld[lv]};
        assign lvvld[lv+1] = vp[4];
        ref_ot_hdc_delay #(.W(TRW + 1), .D(5)) u_t (.clk(clk), .rst_n(rst_n), .d(lvt[lv]), .q(lvt[lv+1]));
    end endgenerate
    assign ov = lvvld[4];
    assign oval = lvv[4][0];
    assign otree = lvt[4][TRW:1];
    assign ofinal = lvt[4][0];
    assign oerr = lve[4][0];
    assign fault = |cfault;
endmodule

files.ref_ot_v41_bf16_lanes2.sv:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// ot_v41_bf16_lanes2: ot_v41_bf16_lanes on the LAT-stage adders (chain2, fadd) for 1.2 GHz at SS (W10).
// ot_v41_bf16_lanes: the optional BF16 path of the V4.1 ROM-array element (W10; model: BF16 lanes on
// 2,048 of the busiest die's 13,798 macros).
//
// Golden mv / matvec_c under R-ARITH chunk8 (tools/hdc_golden_v41.py): products w * bf16(x) in binary32 (a
// BF16 x BF16 product is exact), each golden chunk of 8 consecutive products summed sequentially from +0,
// chunk sums combined by the padded pairwise tree.  A BF16 unit is a lane group of 16 consecutive golden
// chunks (128 elements); word b of a unit carries element b of each chunk (lane l <- chunk 16h + l), so
// each of the 16 lanes runs its own chunk chains (NCHB slots, one pipelined FP32 adder).  The 16 chunk sums
// of a unit complete in the same cycle and meet in a 15-adder, 4-level pairwise tree whose root is the
// golden level-4 node of that lane group; it leaves as one base node for the element's segment tree.
// Latency: product 5 (ot_v41_bmul2) + chain 5 + tree 20.
// The product is ot_v41_bmul2 (= W13b's ot_hdc_bmul SPLIT = 1): two 8x4 partial products in stage 2, a keep-prefix add in
// stage 3.  The single-stage 8x8 product was the column pair's SS endpoint (c1, ideal clock: u_m.s2_p[15], -154.7 ps,
// 848 ps of product logic).  Bit-identical (SPLIT 0 vs 1: 4,393,224 cycles, 0 mismatches) and latency unchanged.
// ---------------------------------------------------------------------------
module ref_ot_v41_bf16_lanes2 #(
    parameter integer NCHB = 8,
    parameter integer GRADUAL_RNE = 0, // shared reviewed multiplier; no stage/port change
    parameter integer TRW = 2,         // tree-id width
    parameter [8:0] CUT = 9'b1_0111_1011,
    parameter integer LAT = 1 + CUT[0] + CUT[1] + CUT[2] + CUT[3] + CUT[4] + CUT[5] + CUT[6] + CUT[7] + CUT[8],
    // RC (BF rowfix re-cut A, 2026-10-07; default 0 = unchanged): bit-identical, +3 product cycles and +2 cycles per
    // tree level (lane latency +11): the product is ot_v41_bmul2_rne_prepare XS = 1 (8 stages); the chunk chains are
    // ot_v41_chain4 (PD = 1, ND = 4 kept forward-select copies: the routed BF HITFIX GRT SS worst -256 ps was one fwd5
    // register driving the operand mux of other lanes and the other macro, merged by synthesis); the 4-level pairwise
    // tree adders (feed-forward) use every stage cut (CUT 1_1111_1111).  The chains keep CUT (their LAT is the issue
    // side's slot-revisit rule).  RC = 2: as RC = 1 but the chunk chains are ot_v41_chain2u2 (unrolled by 2 on a
    // half-rate gated clock, bit-exact, +3 cycles; multicycle 2/1 SDC on their hs_* registers).
    parameter integer RC = 0
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              v,
    input  wire [255:0]      w,        // 16 BF16 weights, lane l at [16l +: 16]
    input  wire [255:0]      x,        // 16 BF16 activations, lane l at [16l +: 16]
    input  wire [$clog2(NCHB)-1:0] slot,
    input  wire              first,
    input  wire              last,
    input  wire [TRW-1:0]    tree,
    input  wire              final_i,
    output wire              ov,
    output wire [31:0]       oval,
    output wire [TRW-1:0]    otree,
    output wire              ofinal,
    output wire              oerr,
    output wire              fault
);
    localparam integer HW = $clog2(NCHB);
    localparam integer TW = HW + 2 + TRW + 1;
    // 1.2 GHz: the word, x slice and tag are registered at the lanes' boundary (the element's capture mux and the
    // 16 lanes' fan-out are not in one cycle)
    reg [255:0] w_r, x_r;
    reg         v_r;
    reg [TW-1:0] t_r;
    always @(posedge clk or negedge rst_n) if (!rst_n) v_r <= 1'b0; else v_r <= v;
    always @(posedge clk) begin w_r <= w; x_r <= x; t_r <= {slot, first, last, tree, final_i}; end
    wire [TW-1:0] t_in = t_r;
    wire [TW-1:0] t_p;
    localparam integer PL = RC != 0 ? 8 : 5;                     // product latency
    localparam [8:0] CUTT = RC != 0 ? 9'b1_1111_1111 : CUT;    // tree adders
    localparam integer LATT = 1 + CUTT[0] + CUTT[1] + CUTT[2] + CUTT[3] + CUTT[4] + CUTT[5] + CUTT[6] + CUTT[7] + CUTT[8];
    ref_ot_hdc_delay #(.W(TW), .D(PL)) u_pt (.clk(clk), .rst_n(rst_n), .d(t_in), .q(t_p));
    wire [15:0] pv;
    wire [15:0] pf;
    wire [31:0] prod [0:15];
    wire [15:0] cv, cf, cfault;
    wire [31:0] cs [0:15];
    wire [TRW:0] ct [0:15];
    genvar l;
    generate for (l = 0; l < 16; l = l + 1) begin : g_l
        ref_ot_v41_bmul2_rne_prepare #(.GRADUAL_RNE(GRADUAL_RNE), .XS(RC != 0 ? 1 : 0)) u_m (.clk(clk), .rst_n(rst_n), .v(v_r), .a({w_r[16*l +: 16], 16'd0}), .b({x_r[16*l +: 16], 16'd0}),
                         .y(prod[l]), .fault(pf[l]));
        reg [PL-1:0] vp;
        always @(posedge clk or negedge rst_n) if (!rst_n) vp <= '0; else vp <= {vp[PL-2:0], v_r};
        assign pv[l] = vp[PL-1];
        if (RC >= 2) begin : g_cu
        ot_v41_chain2u2 #(.NCH(NCHB), .TW(TRW + 1), .CUT(CUT)) u_c (.clk(clk), .rst_n(rst_n), .v(pv[l]),
            .slot(t_p[TW-1 -: HW]), .first(t_p[TRW+2]), .last(t_p[TRW+1]), .term(prod[l]), .term_f(pf[l]),
            .tag(t_p[TRW:0]), .ov(cv[l]), .osum(cs[l]), .of(cf[l]), .otag(ct[l]), .fault(cfault[l]));
        end else if (RC != 0) begin : g_c4
        ot_v41_chain4 #(.PD(1), .ND(4), .NCH(NCHB), .TW(TRW + 1), .CUT(CUT)) u_c (.clk(clk), .rst_n(rst_n), .v(pv[l]),
            .slot(t_p[TW-1 -: HW]), .first(t_p[TRW+2]), .last(t_p[TRW+1]), .term(prod[l]), .term_f(pf[l]),
            .tag(t_p[TRW:0]), .ov(cv[l]), .osum(cs[l]), .of(cf[l]), .otag(ct[l]), .fault(cfault[l]));
        end else begin : g_c2
        ref_ot_v41_chain2 #(.NCH(NCHB), .TW(TRW + 1), .CUT(CUT)) u_c (.clk(clk), .rst_n(rst_n), .v(pv[l]),
            .slot(t_p[TW-1 -: HW]), .first(t_p[TRW+2]), .last(t_p[TRW+1]), .term(prod[l]), .term_f(pf[l]),
            .tag(t_p[TRW:0]), .ov(cv[l]), .osum(cs[l]), .of(cf[l]), .otag(ct[l]), .fault(cfault[l]));
        end
    end endgenerate
    // 4-level pairwise tree over the 16 chunk sums (all lanes emit in the same cycle)
    wire [31:0] lvv [0:4][0:15];
    wire [15:0] lve [0:4];
    wire [4:0] lvvld;
    wire [TRW:0] lvt [0:4];
    generate for (l = 0; l < 16; l = l + 1) begin : g_in
        assign lvv[0][l] = cs[l];
        assign lve[0][l] = cf[l];
    end endgenerate
    assign lvvld[0] = cv[0];
    assign lvt[0] = ct[0];
    genvar lv, k;
    generate for (lv = 0; lv < 4; lv = lv + 1) begin : g_lv
        localparam integer NN = 16 >> (lv + 1);
        for (k = 0; k < NN; k = k + 1) begin : g_n
            wire [1:0] e;
            wire vo;
            ref_ot_v41_fadd #(.CUT(CUTT)) u_a (.clk(clk), .rst_n(rst_n), .valid_in(lvvld[lv]), .a(lvv[lv][2*k]),
                                          .b(lvv[lv][2*k+1]), .y(lvv[lv+1][k]), .err(e), .valid_out(vo));
            reg [LATT-1:0] ep;
            always @(posedge clk) ep <= {ep[LATT-2:0], lve[lv][2*k] | lve[lv][2*k+1]};
            assign lve[lv+1][k] = ep[LATT-1] | (e != 2'd0);
        end
        for (k = NN; k < 16; k = k + 1) begin : g_z
            assign lvv[lv+1][k] = 32'd0;
            assign lve[lv+1][k] = 1'b0;
        end
        reg [LATT-1:0] vp;
        always @(posedge clk or negedge rst_n) if (!rst_n) vp <= '0; else vp <= {vp[LATT-2:0], lvvld[lv]};
        assign lvvld[lv+1] = vp[LATT-1];
        ref_ot_hdc_delay #(.W(TRW + 1), .D(LATT)) u_t (.clk(clk), .rst_n(rst_n), .d(lvt[lv]), .q(lvt[lv+1]));
    end endgenerate
    assign ov = lvvld[4];
    assign oval = lvv[4][0];
    assign otree = lvt[4][TRW:1];
    assign ofinal = lvt[4][0];
    assign oerr = lve[4][0];
    assign fault = |cfault;
endmodule

files.ref_ot_v41_bmul2.sv:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// ot_v41_bmul2: ot_hdc_bmul (rtl/hdc/ot_hdc_fpu.sv) with the 8x8 significand product split across stages 2 and 3,
// for the 1.2 GHz BF16 column lanes (ot_v41_bf16_lanes2).  Stage 2 forms the two 8x4 partial products, stage 3 adds
// them (ot_v41_ksadd, keep-prefix) before its normalise select.  The single-stage product was the column pair's SS
// endpoint (c1, ideal clock: u_m.s2_p[15] at -154.7 ps, 848 ps of product logic).  Same split as W13b's ot_hdc_bmul
// SPLIT = 1 (claude/w13-blockdot12 a2f92966); a separate module so the 40 records pinning ot_hdc_fpu.sv stay current.
// Bit-identical to ot_hdc_bmul (y and fault), LATENCY 5, same ports.
// ---------------------------------------------------------------------------
module ref_ot_v41_bmul2 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] a,
    input  wire [31:0] b,
    output reg  [31:0] y,
    output reg         fault
);
    // stage 1: decode; a subnormal significand is normalised by its top bit
    function automatic [17:0] dec;   // {sig[7:0], E[9:0] signed}
        input [7:0] e;
        input [6:0] m;
        integer i;
        reg [2:0] p;
        begin
            if (e != 0) dec = {1'b1, m, e - 10'sd127};
            else begin
                p = 0;
                for (i = 0; i < 7; i = i + 1) if (m[i]) p = i[2:0];
                dec = {({1'b0, m} << (7 - p)), $signed(-10'sd133) + $signed({7'd0, p})};
            end
        end
    endfunction
    wire [17:0] da = dec(a[30:23], a[22:16]);
    wire [17:0] db = dec(b[30:23], b[22:16]);
    reg        s1_v, s1_s, s1_z, s1_nf;
    reg [7:0]  s1_a, s1_b;
    reg signed [10:0] s1_e;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s1_v <= 1'b0;
        else s1_v <= v;
    end
    always @(posedge clk) begin
        s1_s <= a[31] ^ b[31];
        s1_z <= (a[30:16] == 15'd0) || (b[30:16] == 15'd0);
        s1_nf <= (a[30:23] == 8'hFF) || (b[30:23] == 8'hFF);
        s1_a <= da[17:10]; s1_b <= db[17:10];
        s1_e <= $signed(da[9:0]) + $signed(db[9:0]);
    end
    // stage 2: the two 8x4 partial products of the significand product
    reg        s2_v, s2_s, s2_z, s2_nf;
    reg [11:0] s2_lo, s2_hi;                   // the two 8x4 partial products
    reg signed [10:0] s2_e;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s2_v <= 1'b0;
        else s2_v <= s1_v;
    end
    always @(posedge clk) begin
        s2_s <= s1_s; s2_z <= s1_z; s2_nf <= s1_nf; s2_e <= s1_e;
        s2_lo <= s1_a * s1_b[3:0]; s2_hi <= s1_a * s1_b[7:4];
    end
    // stage 3 first adds the partial products: a*b = a*b[7:4]*16 + a*b[3:0]; the high 12 bits are a 12-bit
    // keep-prefix add (<= 255*15 + 239 = 4064, no carry out).
    wire [11:0] hi_sum;
    wire        hi_co;
    ref_ot_v41_ksadd #(.W(12)) u_ph (.a(s2_hi), .b({4'd0, s2_lo[11:4]}), .cin(1'b0), .s(hi_sum), .cout(hi_co));
    wire [15:0] pq = {hi_sum, s2_lo[3:0]};
    // stage 3: normalise (leading bit 15 or 14) and bias
    reg        s3_v, s3_s, s3_z, s3_nf;
    reg [22:0] s3_f;
    reg signed [10:0] s3_be;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s3_v <= 1'b0;
        else s3_v <= s2_v;
    end
    always @(posedge clk) begin
        s3_s <= s2_s; s3_z <= s2_z; s3_nf <= s2_nf;
        if (pq[15]) begin s3_f <= {pq[14:0], 8'd0}; s3_be <= s2_e + 11'sd128; end
        else          begin s3_f <= {pq[13:0], 9'd0}; s3_be <= s2_e + 11'sd127; end
    end
    // stage 4: encode; a subnormal result shifts right by 1 - biased (<= 7)
    reg        s4_v, s4_bad;
    reg [31:0] s4_y;
    wire [23:0] sig24 = {1'b1, s3_f};
    wire [3:0]  sub_sh = 4'd1 - s3_be[3:0];
    wire [23:0] sub_v = sig24 >> sub_sh;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s4_v <= 1'b0;
        else s4_v <= s3_v;
    end
    always @(posedge clk) begin
        s4_bad <= 1'b0;
        if (s3_z && !s3_nf) s4_y <= 32'd0;
        else if (s3_nf || s3_be > 11'sd254 || s3_be < -11'sd6) begin s4_y <= 32'd0; s4_bad <= 1'b1; end
        else if (s3_be >= 11'sd1) s4_y <= {s3_s, s3_be[7:0], s3_f};
        else s4_y <= {s3_s, 8'd0, sub_v[22:0]};
    end
    // stage 5: output register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin y <= 32'd0; fault <= 1'b0; end
        else begin y <= s4_y; fault <= s4_v && s4_bad; end
    end
endmodule

files.ref_ot_v41_bterm.sv:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// ot_v41_bterm: one exact scaled block term of golden linear_q (tools/hdc_golden_v41.py):
// the 32-wide E4M3 x E4M3 (or E2M1) block dot formed exactly, rounded ONCE to binary32 and
// scaled by 2^(xe + we) -- the term every lane of the V4.1 ROM element feeds its chunk chain.
// Stages P0..P8 are ot_hdc_blockdot's (rtl/hdc/v41/ot_hdc_blockdot.sv, qualified 1195.7 MHz),
// copied verbatim; the accumulator is left to the caller.  `tag` rides alongside.
// LATENCY = 9: a block presented with v in cycle t leaves as ov in cycle t + 9.
// f = NaN code or scaled overflow (fail closed).  Zero terms are +0.
// ---------------------------------------------------------------------------
// (copied from rtl/hdc/v41/ot_hdc_blockdot.sv ot_hdc_v41_csa) Carry-save reduction of N W-bit operands (mod 2^W) to at most M, by levels of
// 3:2 compressors; operands that do not fill a triple pass to the next level.
module ref_ot_v41_csa #(
    parameter integer N = 32,
    parameter integer M = 2,
    parameter integer W = 42
) (
    input  wire [N*W-1:0] d,
    output wire [M*W-1:0] q
);
    function automatic integer nxt(input integer n);
        nxt = 2 * (n / 3) + (n % 3);
    endfunction
    function automatic integer nlev(input integer n, input integer m);
        integer c, k;
        begin
            nlev = 0; c = n;
            for (k = 0; k < 64; k = k + 1)
                if (c > m) begin c = nxt(c); nlev = nlev + 1; end
        end
    endfunction
    function automatic integer cnt(input integer n, input integer l);
        integer k;
        begin
            cnt = n;
            for (k = 0; k < l; k = k + 1) cnt = nxt(cnt);
        end
    endfunction
    function automatic integer off(input integer n, input integer l);
        integer k, c;
        begin
            off = 0; c = n;
            for (k = 0; k < l; k = k + 1) begin off = off + c; c = nxt(c); end
        end
    endfunction
    localparam integer L = nlev(N, M);
    localparam integer NF = cnt(N, L);
    localparam integer OL = off(N, L);
    localparam integer TOT = OL + NF;
    wire [W-1:0] op [0:TOT-1] /*verilator split_var*/;
    genvar i, l;
    generate
        for (i = 0; i < N; i = i + 1) begin : g_in
            assign op[i] = d[W*i +: W];
        end
        for (l = 0; l < L; l = l + 1) begin : g_lvl
            localparam integer NI = cnt(N, l);
            localparam integer OI = off(N, l);
            localparam integer OO = off(N, l + 1);
            localparam integer G3 = NI / 3;
            for (i = 0; i < G3; i = i + 1) begin : g_fa
                wire [W-1:0] a = op[OI + 3*i];
                wire [W-1:0] b = op[OI + 3*i + 1];
                wire [W-1:0] c = op[OI + 3*i + 2];
                wire [W-1:0] mj = (a & b) | (a & c) | (b & c);
                assign op[OO + 2*i] = a ^ b ^ c;
                assign op[OO + 2*i + 1] = {mj[W-2:0], 1'b0};
            end
            for (i = 0; i < NI % 3; i = i + 1) begin : g_pass
                assign op[OO + 2*G3 + i] = op[OI + 3*G3 + i];
            end
        end
        for (i = 0; i < M; i = i + 1) begin : g_out
            if (i < NF) begin : g_op
                assign q[W*i +: W] = op[OL + i];
            end else begin : g_zero
                assign q[W*i +: W] = {W{1'b0}};
            end
        end
    endgenerate
endmodule


module ref_ot_v41_bterm #(
    parameter integer TW = 8
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              v,
    input  wire              fp4,
    input  wire [255:0]      xq,
    input  wire signed [9:0] xe,
    input  wire [255:0]      wq,
    input  wire signed [9:0] we,
    input  wire [TW-1:0]     tag,
    output wire              ov,
    output wire [31:0]       y,
    output wire              f,
    output wire [TW-1:0]     otag
);
    localparam integer W = 42;
    wire first = 1'b0, last = 1'b0;
    function automatic [7:0] e2m1(input [3:0] c);
        if (c[2:1] == 2'd0) e2m1 = {c[3], c[0] ? 4'd6 : 4'd0, 3'd0};
        else                e2m1 = {c[3], {2'b00, c[2:1]} + 4'd6, c[0], 2'b00};
    endfunction


    integer i;

    // -- P0: input register -----------------------------------------------------------
    reg              p0_v, p0_first, p0_last, p0_fp4;
    reg [255:0]      p0_xq, p0_wq;
    reg signed [9:0] p0_xe, p0_we;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) p0_v <= 1'b0;
        else p0_v <= v;
    end
    always @(posedge clk) begin
        p0_first <= first; p0_last <= last; p0_fp4 <= fp4;
        p0_xq <= xq; p0_wq <= wq; p0_xe <= xe; p0_we <= we;
    end

    // -- P1: decode, signed 4x4 products, shift amounts -----------------------------------
    reg               p1_v, p1_first, p1_last, p1_nan;
    reg signed [10:0] p1_es;
    reg signed [8:0]  p1_p [0:31];
    reg [4:0]         p1_sh [0:31];
    reg [7:0]         xc, wc;
    reg [3:0]         xs, ws, xf, wf;
    reg [7:0]         pm;
    reg               nan;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) p1_v <= 1'b0;
        else p1_v <= p0_v;
    end
    always @(posedge clk) begin
        p1_first <= p0_first; p1_last <= p0_last;
        p1_es <= p0_xe + p0_we;
        nan = 1'b0;
        for (i = 0; i < 32; i = i + 1) begin
            xc = p0_xq[8*i +: 8];
            wc = p0_fp4 ? e2m1(p0_wq[8*i +: 4]) : p0_wq[8*i +: 8];
            nan = nan | (xc[6:0] == 7'h7F) | (wc[6:0] == 7'h7F);
            xs = {(xc[6:3] != 4'd0), xc[2:0]};
            ws = {(wc[6:3] != 4'd0), wc[2:0]};
            xf = (xc[6:3] == 4'd0) ? 4'd1 : xc[6:3];
            wf = (wc[6:3] == 4'd0) ? 4'd1 : wc[6:3];
            pm = xs * ws;
            p1_p[i] <= (xc[7] ^ wc[7]) ? -$signed({1'b0, pm}) : $signed({1'b0, pm});
            p1_sh[i] <= {1'b0, xf} + {1'b0, wf} - 5'd2;
        end
        p1_nan <= nan;
    end

    // -- P2: terms (units of 2^-18) and CSA 32 -> 7 ---------------------------------------
    reg [32*W-1:0] terms;
    always @(*) begin
        for (i = 0; i < 32; i = i + 1)
            terms[W*i +: W] = {{(W-9){p1_p[i][8]}}, p1_p[i]} << p1_sh[i];
    end
    wire [7*W-1:0] c7;
    ref_ot_v41_csa #(.N(32), .M(7), .W(W)) u_csa1 (.d(terms), .q(c7));
    reg               p2_v, p2_first, p2_last, p2_nan;
    reg signed [10:0] p2_es;
    reg [7*W-1:0]     p2_c;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) p2_v <= 1'b0;
        else p2_v <= p1_v;
    end
    always @(posedge clk) begin
        p2_first <= p1_first; p2_last <= p1_last; p2_nan <= p1_nan; p2_es <= p1_es;
        p2_c <= c7;
    end

    // -- P3: CSA 7 -> 2 ------------------------------------------------------------------------
    wire [2*W-1:0] c2;
    ref_ot_v41_csa #(.N(7), .M(2), .W(W)) u_csa2 (.d(p2_c), .q(c2));
    reg               p3_v, p3_first, p3_last, p3_nan;
    reg signed [10:0] p3_es;
    reg [W-1:0]       p3_a, p3_b;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) p3_v <= 1'b0;
        else p3_v <= p2_v;
    end
    always @(posedge clk) begin
        p3_first <= p2_first; p3_last <= p2_last; p3_nan <= p2_nan; p3_es <= p2_es;
        p3_a <= c2[W-1:0]; p3_b <= c2[2*W-1:W];
    end

    // -- P4: sum and its negation in parallel; sign-magnitude -------------------------------------
    wire [W-1:0] sp = p3_a + p3_b;
    wire [W-1:0] sn = ~p3_a + ~p3_b + {{(W-2){1'b0}}, 2'd2};     // -(a + b)
    reg               p4_v, p4_first, p4_last, p4_nan, p4_s;
    reg signed [11:0] p4_eb;
    reg [W-2:0]       p4_m;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) p4_v <= 1'b0;
        else p4_v <= p3_v;
    end
    always @(posedge clk) begin
        p4_first <= p3_first; p4_last <= p3_last; p4_nan <= p3_nan;
        //: biased exponent of the leading bit at position 40 is xe + we + 149
        p4_eb <= p3_es + 12'sd149;
        p4_s <= sp[W-1];
        p4_m <= sp[W-1] ? sn[W-2:0] : sp[W-2:0];
    end

    // -- P5: normalise ----------------------------------------------------------------------------
    reg [40:0] nm;
    reg [5:0]  lz;
    always @(*) begin
        nm = p4_m; lz = 6'd0;
        if (nm[40:9]  == 32'd0) begin nm = nm << 32; lz = lz + 6'd32; end
        if (nm[40:25] == 16'd0) begin nm = nm << 16; lz = lz + 6'd16; end
        if (nm[40:33] == 8'd0)  begin nm = nm << 8;  lz = lz + 6'd8;  end
        if (nm[40:37] == 4'd0)  begin nm = nm << 4;  lz = lz + 6'd4;  end
        if (nm[40:39] == 2'd0)  begin nm = nm << 2;  lz = lz + 6'd2;  end
        if (nm[40] == 1'b0)     begin nm = nm << 1;  lz = lz + 6'd1;  end
    end
    reg               p5_v, p5_first, p5_last, p5_nan, p5_s, p5_z;
    reg signed [11:0] p5_eb;
    reg [40:0]        p5_nm;
    reg [5:0]         p5_lz;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) p5_v <= 1'b0;
        else p5_v <= p4_v;
    end
    always @(posedge clk) begin
        p5_first <= p4_first; p5_last <= p4_last; p5_nan <= p4_nan; p5_s <= p4_s;
        p5_z <= (p4_m == 41'd0);
        p5_eb <= p4_eb; p5_nm <= nm; p5_lz <= lz;
    end

    // -- P6: round to 24 bits (the golden's float32 of the exact dot) -----------------------------
    wire [23:0] m24 = p5_nm[40:17];
    wire        inc = p5_nm[16] & ((p5_nm[15:0] != 16'd0) | m24[0]);
    wire [24:0] mr = {1'b0, m24} + {24'd0, inc};
    reg               p6_v, p6_first, p6_last, p6_nan, p6_s, p6_z;
    reg signed [11:0] p6_b;
    reg [22:0]        p6_f;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) p6_v <= 1'b0;
        else p6_v <= p5_v;
    end
    always @(posedge clk) begin
        p6_first <= p5_first; p6_last <= p5_last; p6_nan <= p5_nan; p6_s <= p5_s; p6_z <= p5_z;
        p6_b <= p5_eb - $signed({6'd0, p5_lz}) + $signed({11'd0, mr[24]});
        p6_f <= mr[24] ? 23'd0 : mr[22:0];
    end

    // -- P7: scale by 2^(xe+we): exponent add done; subnormal right shift -------------------------
    wire [11:0] rsh = 12'd1 - p6_b;                         // used when p6_b <= 0
    wire [4:0]  rs5 = (p6_b < -12'sd24) ? 5'd26 : rsh[4:0];
    wire [49:0] sw = {1'b1, p6_f, 26'd0} >> rs5;
    reg               p7_v, p7_first, p7_last, p7_nan, p7_sub, p7_ovf, p7_s;
    reg [31:0]        p7_n;                                 // normal / zero / inf result
    reg [23:0]        p7_t;
    reg               p7_g, p7_st;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) p7_v <= 1'b0;
        else p7_v <= p6_v;
    end
    always @(posedge clk) begin
        p7_first <= p6_first; p7_last <= p6_last; p7_nan <= p6_nan; p7_s <= p6_s;
        p7_sub <= !p6_z && (p6_b < 12'sd1);
        p7_ovf <= !p6_z && (p6_b > 12'sd254);
        if (p6_z)                  p7_n <= 32'd0;
        else if (p6_b > 12'sd254)  p7_n <= {p6_s, 8'hFF, 23'd0};
        else                       p7_n <= {p6_s, p6_b[7:0], p6_f};
        p7_t <= sw[49:26];
        p7_g <= sw[25];
        p7_st <= (sw[24:0] != 25'd0);
    end

    // -- P8: subnormal round and pack ---------------------------------------------------------------
    wire [23:0] tr = p7_t + {23'd0, p7_g & (p7_st | p7_t[0])};
    reg         p8_v, p8_first, p8_last, p8_f;
    reg [31:0]  p8_y;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) p8_v <= 1'b0;
        else p8_v <= p7_v;
    end
    always @(posedge clk) begin
        p8_first <= p7_first; p8_last <= p7_last;
        p8_f <= p7_nan | p7_ovf;
        //: a subnormal that rounds up to 2^-126 carries into the exponent field
        p8_y <= p7_sub ? {p7_s, 7'd0, tr} : p7_n;
    end

    assign ov = p8_v;
    assign y = p8_y;
    assign f = p8_f;
    ref_ot_hdc_delay #(.W(TW), .D(9)) u_tag (.clk(clk), .rst_n(rst_n), .d(tag), .q(otag));
endmodule

