`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// ot_v41_segtree: the golden csum padded pairwise tree over one segment's chunk sums, for up to NT
// segments (trees) in flight, on ONE pipelined binary32 adder (ot_fp32_add_rne_pipe, 5 cycles).
//
// Base nodes of a tree arrive IN ORDER (FP8 chunk sums, FP4 chunk-pair sums); `final` marks the tree's last.
// An event {tree, level, value, final} at level l either pairs with the tree's held left operand of level l
// (held + value, left first) or, if none is held, is held -- unless it is final, when it is promoted to
// level l+1 by adding +0 (the golden's padding; x + 0 = x here, since no zero is -0).  Both go through the
// adder (operands registered first: 6 cycles per level), so every event at level l+1 leaves the adder in the
// order its level-l inputs entered it, and a
// promoted final can never overtake an in-flight sum of its own tree.  A final event at level LV leaves as
// the segment's partial.  Base nodes queue in a QD-entry FIFO while the adder serves its own results first.
// Adds per tree: (base nodes - 1) + at most LV promotions -- under one per cycle for any base-node rate the
// element can produce, so one adder replaces LV.
// ---------------------------------------------------------------------------
module cand_ot_v41_segtree #(
    parameter integer NT = 4,
    parameter integer LV = 5,
    parameter integer QD = 8,
    parameter integer EARLY = 0      // 1: a final node with nothing held above it and nothing of its tree in the
                                     //    adder leaves at once instead of being promoted (+0) level by level
) (
    input  wire                     clk,
    input  wire                     rst_n,
    input  wire                     in_v,
    input  wire [$clog2(NT)-1:0]    in_tree,
    input  wire [2:0]               in_pos,     // position (MTP) of the tree's nodes; leaves with its value
    input  wire [31:0]              in_val,
    input  wire                     in_final,
    input  wire                     in_err,
    output reg                      ov,
    output reg  [$clog2(NT)-1:0]    otree,
    output reg  [2:0]               opos,
    output reg  [31:0]              oval,
    output reg                      oerr,
    output reg                      fault
);
    localparam integer PW = $clog2(NT);
    localparam integer LW = $clog2(LV + 1);
    localparam integer QW = $clog2(QD);
    // base-node queue
    reg [31:0] qv [0:QD-1];
    reg [PW-1:0] qt [0:QD-1];
    reg qf [0:QD-1], qe [0:QD-1];
    reg [2:0] qp [0:QD-1];
    reg [2:0] tpos [0:NT-1];
    reg [QW-1:0] qr, qw;
    reg [QW:0] qc;
    // held left operands
    reg [31:0] held [0:NT*LV-1];
    reg [NT*LV-1:0] have, herr;
    // adder result (event at level + 1)
    wire [31:0] sum;
    wire [1:0] err;
    wire sv;
    wire [PW+LW+1:0] st;     // {tree, level, final, err}
    // the event considered this cycle: adder result first, else the queue head
    wire use_q = !sv && qc != 0;
    // the queue head is held in registers (loaded from the entry the pop will expose, or the incoming node when
    // that entry is being written now), so the event select is a 2-way choice, not a QD-way read
    reg [31:0] h_v;
    reg [PW-1:0] h_t;
    reg h_f, h_e;
    reg [2:0] h_p;
    wire        e_v = sv || qc != 0;
    wire [PW-1:0] e_t = sv ? st[PW+LW+1 -: PW] : h_t;
    wire [LW-1:0] e_l = sv ? st[LW+1 -: LW] : {LW{1'b0}};
    wire        e_f = sv ? st[1] : h_f;
    wire        e_e = sv ? (st[0] | err != 2'd0) : h_e;
    wire [31:0] e_d = sv ? sum : h_v;
    wire [PW+LW-1:0] hidx = e_t * LV + e_l;
    // trees' events inside the adder, and whether a tree holds anything above level e_l
    reg [2:0] infl [0:NT-1];
    reg above;
    integer li, ti;
    always @* begin
        above = 1'b0;
        for (li = 0; li < LV; li = li + 1)
            if (li > e_l && have[e_t * LV + li]) above = 1'b1;
    end
    wire mine_out = sv;                               // the event leaving the adder now is e_t's own
    wire idle_tree = infl[e_t] == (mine_out ? 3'd1 : 3'd0);
    wire early = (EARLY != 0) && e_v && e_f && !have[hidx] && !above && idle_tree;
    wire top = e_l == LV[LW-1:0] || early;
    wire pair = e_v && !top && have[hidx];
    wire promote = e_v && !top && !have[hidx] && e_f;
    wire hold = e_v && !top && !have[hidx] && !e_f;
    wire [PW-1:0] out_t = st[PW+LW+1 -: PW];
    // the operands are registered before the adder (the event select and the held-operand lookup would
    // otherwise sit in front of the adder's first stage); an add takes 6 cycles from its decision
    reg [31:0] add_a, add_b;
    reg        add_v;
    always @(posedge clk) begin
        add_a <= pair ? held[hidx] : e_d;
        add_b <= pair ? e_d : 32'd0;
    end
    always @(posedge clk or negedge rst_n)
        if (!rst_n) add_v <= 1'b0; else add_v <= pair | promote;
    cand_ot_fp32_add_rne_pipe u_add (.clk(clk), .rst_n(rst_n), .valid_in(add_v), .a(add_a), .b(add_b),
                                .y(sum), .err(err), .valid_out(sv));
    cand_ot_hdc_delay #(.W(PW + LW + 2), .D(6)) u_t (.clk(clk), .rst_n(rst_n),
        .d({e_t, e_l + 1'b1, e_f, e_e | (pair && herr[hidx])}), .q(st));
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            qr <= 0; qw <= 0; qc <= 0; have <= '0; herr <= '0; ov <= 1'b0; oerr <= 1'b0; fault <= 1'b0;
            for (ti = 0; ti < NT; ti = ti + 1) infl[ti] <= 3'd0;
        end else begin
            if (in_v) qw <= qw + 1'b1;
            if (use_q) qr <= qr + 1'b1;
            qc <= qc + (in_v ? 1'b1 : 1'b0) - (use_q ? 1'b1 : 1'b0);
            if (in_v && qc == QD && !use_q) fault <= 1'b1;
            for (ti = 0; ti < NT; ti = ti + 1)
                infl[ti] <= infl[ti] + (((pair | promote) && e_t == ti) ? 3'd1 : 3'd0)
                                     - ((sv && out_t == ti) ? 3'd1 : 3'd0);
            if (pair) have[hidx] <= 1'b0;
            if (hold) begin have[hidx] <= 1'b1; herr[hidx] <= e_e; end
            ov <= e_v && top;
            oerr <= e_v && top && e_e;
        end
    end
    always @(posedge clk) begin
        if (in_v) begin qv[qw] <= in_val; qt[qw] <= in_tree; qf[qw] <= in_final; qe[qw] <= in_err; qp[qw] <= in_pos; end
        if (use_q) tpos[h_t] <= h_p;
        opos <= use_q ? h_p : tpos[e_t];
        if (qr + (use_q ? 1'b1 : 1'b0) == qw) begin      // the head-to-be is the node arriving now (if any)
            h_v <= in_val; h_t <= in_tree; h_f <= in_final; h_e <= in_err; h_p <= in_pos;
        end else begin
            h_v <= qv[qr + (use_q ? 1'b1 : 1'b0)]; h_t <= qt[qr + (use_q ? 1'b1 : 1'b0)];
            h_f <= qf[qr + (use_q ? 1'b1 : 1'b0)]; h_e <= qe[qr + (use_q ? 1'b1 : 1'b0)];
            h_p <= qp[qr + (use_q ? 1'b1 : 1'b0)];
        end
        if (hold) held[hidx] <= e_d;
        oval <= e_d;
        otree <= e_t;
    end
endmodule

files.cand_ot_v41_segtree2.sv:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// ot_v41_segtree2: ot_v41_segtree on the LAT-stage ot_v41_fadd with the adder result registered before it is
// an event and a 2-stage event pipeline (select + one-hot decode | decide) (W10, 1.2 GHz at SS): LAT + 3
// cycles per level (was 6).  Same order and results.
// ot_v41_segtree: the golden csum padded pairwise tree over one segment's chunk sums, for up to NT
// segments (trees) in flight, on ONE pipelined binary32 adder (ot_fp32_add_rne_pipe, 5 cycles).
//
// Base nodes of a tree arrive IN ORDER (FP8 chunk sums, FP4 chunk-pair sums); `final` marks the tree's last.
// An event {tree, level, value, final} at level l either pairs with the tree's held left operand of level l
// (held + value, left first) or, if none is held, is held -- unless it is final, when it is promoted to
// level l+1 by adding +0 (the golden's padding; x + 0 = x here, since no zero is -0).  Both go through the
// adder (operands registered first: 6 cycles per level), so every event at level l+1 leaves the adder in the
// order its level-l inputs entered it, and a
// promoted final can never overtake an in-flight sum of its own tree.  A final event at level LV leaves as
// the segment's partial.  Base nodes queue in a QD-entry FIFO while the adder serves its own results first.
// Adds per tree: (base nodes - 1) + at most LV promotions -- under one per cycle for any base-node rate the
// element can produce, so one adder replaces LV.
// ---------------------------------------------------------------------------
module cand_ot_v41_segtree2 #(
    parameter integer NT = 4,
    parameter integer LV = 5,
    parameter integer QD = 8,
    parameter [8:0] CUT = 9'b1_0111_1011,
    parameter integer LAT = 1 + CUT[0] + CUT[1] + CUT[2] + CUT[3] + CUT[4] + CUT[5] + CUT[6] + CUT[7] + CUT[8],
    parameter integer EARLY = 0      // 1: a final node with nothing held above it and nothing of its tree in the
                                     //    adder leaves at once instead of being promoted (+0) level by level
) (
    input  wire                     clk,
    input  wire                     rst_n,
    input  wire                     in_v,
    input  wire [$clog2(NT)-1:0]    in_tree,
    input  wire [2:0]               in_pos,     // position (MTP) of the tree's nodes; leaves with its value
    input  wire [31:0]              in_val,
    input  wire                     in_final,
    input  wire                     in_err,
    output reg                      ov,
    output reg  [$clog2(NT)-1:0]    otree,
    output reg  [2:0]               opos,
    output reg  [31:0]              oval,
    output reg                      oerr,
    output reg                      fault
);
    localparam integer PW = $clog2(NT);
    localparam integer LW = $clog2(LV + 1);
    localparam integer QW = $clog2(QD);
    // base-node queue
    reg [31:0] qv [0:QD-1];
    reg [PW-1:0] qt [0:QD-1];
    reg qf [0:QD-1], qe [0:QD-1];
    reg [2:0] qp [0:QD-1];
    reg [2:0] tpos [0:NT-1];
    reg [QW-1:0] qr, qw;
    reg [QW:0] qc;
    // held left operands
    reg [31:0] held [0:NT*LV-1];
    reg [NT*LV-1:0] have, herr;
    // adder result (event at level + 1), registered once before it is an event (1.2 GHz: the event decision and
    // the held-operand write no longer follow the adder's output stage in the same cycle)
    wire [31:0] sum_a;
    wire [1:0] err_a;
    wire sv_a;
    wire [PW+LW+1:0] st_a;
    reg  [31:0] sum;
    reg  [1:0] err;
    reg  sv;
    reg  [PW+LW+1:0] st;     // {tree, level, final, err}
    always @(posedge clk or negedge rst_n) if (!rst_n) sv <= 1'b0; else sv <= sv_a;
    always @(posedge clk) begin sum <= sum_a; err <= err_a; st <= st_a; end
    // STAGE 1 -- the event considered this cycle: adder result first, else the queue head.  It is registered
    // (x_*) with its held-operand index decoded one-hot and the mask of its tree's levels above it, so the
    // decision stage below is a few AND-OR levels over registers (1.2 GHz at SS).  An event spends one cycle in
    // each stage; the decision stage reads and writes the held operands in the same cycle, so consecutive
    // events of one tree see each other's updates.
    wire use_q = !sv && qc != 0;
    reg [31:0] h_v;
    reg [PW-1:0] h_t;
    reg h_f, h_e;
    reg [2:0] h_p;
    wire        e_v = sv || qc != 0;
    wire [PW-1:0] e_t = sv ? st[PW+LW+1 -: PW] : h_t;
    wire [LW-1:0] e_l = sv ? st[LW+1 -: LW] : {LW{1'b0}};
    wire        e_f = sv ? st[1] : h_f;
    wire        e_e = sv ? (st[0] | err != 2'd0) : h_e;
    wire [31:0] e_d = sv ? sum : h_v;
    localparam integer NH = NT * LV;
    reg [NH-1:0] e_oh, e_above;
    integer li, ti, hi;
    always @* begin
        e_oh = '0; e_above = '0;
        for (hi = 0; hi < NH; hi = hi + 1) begin
            if (hi / LV == e_t && hi % LV == e_l) e_oh[hi] = 1'b1;
            if (hi / LV == e_t && hi % LV > e_l) e_above[hi] = 1'b1;
        end
    end
    reg          x_v, x_f, x_e, x_add;
    reg [PW-1:0] x_t;
    reg [LW-1:0] x_l;
    reg [31:0]   x_d;
    reg [NH-1:0] x_oh, x_above;
    reg [2:0]    x_pos;
    always @(posedge clk or negedge rst_n) if (!rst_n) x_v <= 1'b0; else x_v <= e_v;
    always @(posedge clk) begin
        x_t <= e_t; x_l <= e_l; x_f <= e_f; x_e <= e_e; x_d <= e_d; x_add <= sv;
        x_oh <= e_oh; x_above <= e_above;
        x_pos <= use_q ? h_p : tpos[e_t];
    end
    // STAGE 2 -- decide: pair with the held left operand, promote a final node (+0), hold it, or emit at the top
    localparam integer IW = $clog2(LAT + 4);
    reg [IW-1:0] infl [0:NT-1];
    wire x_have = |(have & x_oh);
    wire above = |(have & x_above);
    wire idle_tree = infl[x_t] == (x_add ? {{(IW-1){1'b0}}, 1'b1} : {IW{1'b0}});
    wire early = (EARLY != 0) && x_v && x_f && !x_have && !above && idle_tree;
    wire top = x_l == LV[LW-1:0] || early;
    wire pair = x_v && !top && x_have;
    wire promote = x_v && !top && !x_have && x_f;
    wire hold = x_v && !top && !x_have && !x_f;
    reg [31:0] x_held;
    reg        x_herr;
    always @* begin
        x_held = 32'd0; x_herr = 1'b0;
        for (hi = 0; hi < NH; hi = hi + 1)
            if (x_oh[hi]) begin x_held = x_held | held[hi]; x_herr = x_herr | herr[hi]; end
    end
    wire [PW-1:0] out_t = x_t;
    reg [31:0] add_a, add_b;
    reg        add_v;
    always @(posedge clk) begin
        add_a <= pair ? x_held : x_d;
        add_b <= pair ? x_d : 32'd0;
    end
    always @(posedge clk or negedge rst_n)
        if (!rst_n) add_v <= 1'b0; else add_v <= pair | promote;
    cand_ot_v41_fadd #(.CUT(CUT)) u_add (.clk(clk), .rst_n(rst_n), .valid_in(add_v), .a(add_a), .b(add_b),
                                     .y(sum_a), .err(err_a), .valid_out(sv_a));
    cand_ot_hdc_delay #(.W(PW + LW + 2), .D(LAT + 1)) u_t (.clk(clk), .rst_n(rst_n),
        .d({x_t, x_l + 1'b1, x_f, x_e | (pair && x_herr)}), .q(st_a));
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            qr <= 0; qw <= 0; qc <= 0; have <= '0; herr <= '0; ov <= 1'b0; oerr <= 1'b0; fault <= 1'b0;
            for (ti = 0; ti < NT; ti = ti + 1) infl[ti] <= '0;
        end else begin
            if (in_v) qw <= qw + 1'b1;
            if (use_q) qr <= qr + 1'b1;
            qc <= qc + (in_v ? 1'b1 : 1'b0) - (use_q ? 1'b1 : 1'b0);
            if (in_v && qc == QD && !use_q) fault <= 1'b1;
            if (x_v && x_l == LV[LW-1:0] && !x_f) fault <= 1'b1;    // more base nodes than 2^LV: not the root
            for (ti = 0; ti < NT; ti = ti + 1)
                infl[ti] <= infl[ti] + (((pair | promote) && x_t == ti) ? 1'b1 : 1'b0)
                                     - ((x_v && x_add && out_t == ti) ? 1'b1 : 1'b0);
            if (pair) have <= have & ~x_oh;
            if (hold) begin have <= have | x_oh; herr <= (herr & ~x_oh) | (x_e ? x_oh : '0); end
            ov <= x_v && top;
            oerr <= x_v && top && x_e;
        end
    end
    always @(posedge clk) begin
        if (in_v) begin qv[qw] <= in_val; qt[qw] <= in_tree; qf[qw] <= in_final; qe[qw] <= in_err; qp[qw] <= in_pos; end
        if (use_q) tpos[h_t] <= h_p;
        opos <= x_pos;
        if (qr + (use_q ? 1'b1 : 1'b0) == qw) begin      // the head-to-be is the node arriving now (if any)
            h_v <= in_val; h_t <= in_tree; h_f <= in_final; h_e <= in_err; h_p <= in_pos;
        end else begin
            h_v <= qv[qr + (use_q ? 1'b1 : 1'b0)]; h_t <= qt[qr + (use_q ? 1'b1 : 1'b0)];
            h_f <= qf[qr + (use_q ? 1'b1 : 1'b0)]; h_e <= qe[qr + (use_q ? 1'b1 : 1'b0)];
            h_p <= qp[qr + (use_q ? 1'b1 : 1'b0)];
        end
        for (hi = 0; hi < NH; hi = hi + 1) if (hold && x_oh[hi]) held[hi] <= x_d;
        oval <= x_d;
        otree <= x_t;
    end
endmodule

files.cand_ot_v41_bmul2_rne_prepare.sv:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// ot_v41_bmul2: ot_hdc_bmul (rtl/hdc/ot_hdc_fpu.sv) with the 8x8 significand product split across stages 2 and 3,
// for the 1.2 GHz BF16 column lanes (ot_v41_bf16_lanes2).  Stage 2 forms the two 8x4 partial products, stage 3 adds
// them (ot_v41_ksadd, keep-prefix) before its normalise select.  The single-stage product was the column pair's SS
// endpoint (c1, ideal clock: u_m.s2_p[15] at -154.7 ps, 848 ps of product logic).  Same split as W13b's ot_hdc_bmul
// SPLIT = 1 (claude/w13-blockdot12 a2f92966); a separate module so the 40 records pinning ot_hdc_fpu.sv stay current.
// Default0 preserves ot_hdc_bmul y/fault. Opt-in1 enables finite gradual-underflow RNE.
// Five cycles and existing registers/engine ports retained. Stage4 SS/FF closure OPEN.
// ---------------------------------------------------------------------------
module cand_ot_v41_bmul2_rne_prepare #(
    parameter integer GRADUAL_RNE = 0, // mandatory finite-domain repair; default preserves baseline
    // XS (BF rowfix re-cut A, 2026-10-07; default 0 = unchanged): +3 pipeline registers, latency 5 -> 8, bit-identical:
    // after the operand decode (stage 1 = exponent add only), after the partial-product add (stage 3 = normalise
    // select only) and after the subnormal RNE encode (stage 4 = result select only).  Routed BF HITFIX GRT at SS:
    // s1_e -212, s3_f -121, s4_y -224 ps.
    parameter integer XS = 0
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] a,
    input  wire [31:0] b,
    output reg  [31:0] y,
    output reg         fault
);
    // stage 1: decode; a subnormal significand is normalised by its top bit
    function automatic [17:0] dec;   // {sig[7:0], E[9:0] signed}
        input [7:0] e;
        input [6:0] m;
        integer i;
        reg [2:0] p;
        begin
            if (e != 0) dec = {1'b1, m, e - 10'sd127};
            else begin
                p = 0;
                for (i = 0; i < 7; i = i + 1) if (m[i]) p = i[2:0];
                dec = {({1'b0, m} << (7 - p)), $signed(-10'sd133) + $signed({7'd0, p})};
            end
        end
    endfunction
    wire [17:0] da0 = dec(a[30:23], a[22:16]);
    wire [17:0] db0 = dec(b[30:23], b[22:16]);
    // XS: stage-1 inputs registered after the decode
    wire [17:0] da, db;
    wire        i_v, i_s, i_z, i_nf;
    if (XS != 0) begin : g_x1
        reg [17:0] r_da, r_db; reg r_v, r_s, r_z, r_nf;
        always @(posedge clk or negedge rst_n) if (!rst_n) r_v <= 1'b0; else r_v <= v;
        always @(posedge clk) begin
            r_da <= da0; r_db <= db0; r_s <= a[31] ^ b[31];
            r_z <= (a[30:16] == 15'd0) || (b[30:16] == 15'd0); r_nf <= (a[30:23] == 8'hFF) || (b[30:23] == 8'hFF);
        end
        assign da = r_da; assign db = r_db; assign i_v = r_v; assign i_s = r_s; assign i_z = r_z; assign i_nf = r_nf;
    end else begin : g_n1
        assign da = da0; assign db = db0; assign i_v = v; assign i_s = a[31] ^ b[31];
        assign i_z = (a[30:16] == 15'd0) || (b[30:16] == 15'd0); assign i_nf = (a[30:23] == 8'hFF) || (b[30:23] == 8'hFF);
    end
    reg        s1_v, s1_s, s1_z, s1_nf;
    reg [7:0]  s1_a, s1_b;
    reg signed [10:0] s1_e;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s1_v <= 1'b0;
        else s1_v <= i_v;
    end
    always @(posedge clk) begin
        s1_s <= i_s;
        s1_z <= i_z;
        s1_nf <= i_nf;
        s1_a <= da[17:10]; s1_b <= db[17:10];
        s1_e <= $signed(da[9:0]) + $signed(db[9:0]);
    end
    // stage 2: the two 8x4 partial products of the significand product
    reg        s2_v, s2_s, s2_z, s2_nf;
    reg [11:0] s2_lo, s2_hi;                   // the two 8x4 partial products
    reg signed [10:0] s2_e;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s2_v <= 1'b0;
        else s2_v <= s1_v;
    end
    always @(posedge clk) begin
        s2_s <= s1_s; s2_z <= s1_z; s2_nf <= s1_nf; s2_e <= s1_e;
        s2_lo <= s1_a * s1_b[3:0]; s2_hi <= s1_a * s1_b[7:4];
    end
    // stage 3 first adds the partial products: a*b = a*b[7:4]*16 + a*b[3:0]; the high 12 bits are a 12-bit
    // keep-prefix add (<= 255*15 + 239 = 4064, no carry out).
    wire [11:0] hi_sum;
    wire        hi_co;
    cand_ot_v41_ksadd #(.W(12)) u_ph (.a(s2_hi), .b({4'd0, s2_lo[11:4]}), .cin(1'b0), .s(hi_sum), .cout(hi_co));
    wire [15:0] pq0 = {hi_sum, s2_lo[3:0]};
    // XS: the product registered before the normalise select
    wire [15:0] pq;
    wire        j_v, j_s, j_z, j_nf;
    wire signed [10:0] j_e;
    if (XS != 0) begin : g_x3
        reg [15:0] r_pq; reg r_v, r_s, r_z, r_nf; reg signed [10:0] r_e;
        always @(posedge clk or negedge rst_n) if (!rst_n) r_v <= 1'b0; else r_v <= s2_v;
        always @(posedge clk) begin r_pq <= pq0; r_s <= s2_s; r_z <= s2_z; r_nf <= s2_nf; r_e <= s2_e; end
        assign pq = r_pq; assign j_v = r_v; assign j_s = r_s; assign j_z = r_z; assign j_nf = r_nf; assign j_e = r_e;
    end else begin : g_n3
        assign pq = pq0; assign j_v = s2_v; assign j_s = s2_s; assign j_z = s2_z; assign j_nf = s2_nf; assign j_e = s2_e;
    end
    // stage 3: normalise (leading bit 15 or 14) and bias
    reg        s3_v, s3_s, s3_z, s3_nf;
    reg [22:0] s3_f;
    reg signed [10:0] s3_be;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s3_v <= 1'b0;
        else s3_v <= j_v;
    end
    always @(posedge clk) begin
        s3_s <= j_s; s3_z <= j_z; s3_nf <= j_nf;
        if (pq[15]) begin s3_f <= {pq[14:0], 8'd0}; s3_be <= j_e + 11'sd128; end
        else          begin s3_f <= {pq[13:0], 9'd0}; s3_be <= j_e + 11'sd127; end
    end
    // stage 4: encode; a subnormal result shifts right by 1 - biased (<= 7)
    reg        s4_v, s4_bad;
    reg [31:0] s4_y;
    wire [23:0] sig24 = {1'b1, s3_f};
    wire [3:0]  sub_sh = 4'd1 - s3_be[3:0];
    wire [23:0] sub_v = sig24 >> sub_sh;
    wire [31:0] gradual_y;
    generate if (GRADUAL_RNE != 0) begin : g_gradual
        cand_ot_v41_bmul_subnormal_rne_prepare u_encode (.sign_i(s3_s), .biased_i(s3_be), .sig_i(sig24), .y(gradual_y));
    end else begin : g_baseline
        assign gradual_y = 32'd0;
    end endgenerate
    // XS: the encodes registered before the result select (k_* = stage-3 fields one cycle later)
    wire        k_v, k_s, k_z, k_nf;
    wire signed [10:0] k_be;
    wire [22:0] k_f, k_sub;
    wire [31:0] k_gy;
    if (XS != 0) begin : g_x4
        reg r_v, r_s, r_z, r_nf; reg signed [10:0] r_be; reg [22:0] r_f, r_sub; reg [31:0] r_gy;
        always @(posedge clk or negedge rst_n) if (!rst_n) r_v <= 1'b0; else r_v <= s3_v;
        always @(posedge clk) begin
            r_s <= s3_s; r_z <= s3_z; r_nf <= s3_nf; r_be <= s3_be; r_sub <= sub_v[22:0]; r_gy <= gradual_y;
`ifdef W10_MUTANT_RECUT
            r_f <= s3_f ^ 23'd1;    // negative control: product significand LSB flipped in the added stage
`else
            r_f <= s3_f;
`endif
        end
        assign k_v = r_v; assign k_s = r_s; assign k_z = r_z; assign k_nf = r_nf; assign k_be = r_be; assign k_f = r_f;
        assign k_sub = r_sub; assign k_gy = r_gy;
    end else begin : g_n4
        assign k_v = s3_v; assign k_s = s3_s; assign k_z = s3_z; assign k_nf = s3_nf; assign k_be = s3_be; assign k_f = s3_f;
        assign k_sub = sub_v[22:0]; assign k_gy = gradual_y;
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) s4_v <= 1'b0;
        else s4_v <= k_v;
    end
    always @(posedge clk) begin
        s4_bad <= 1'b0;
        if (k_z && !k_nf) s4_y <= 32'd0;
        else if (k_nf || k_be > 11'sd254 || (GRADUAL_RNE == 0 && k_be < -11'sd6)) begin s4_y <= 32'd0; s4_bad <= 1'b1; end
        else if (k_be >= 11'sd1) s4_y <= {k_s, k_be[7:0], k_f};
        else if (GRADUAL_RNE != 0) s4_y <= k_gy;
        else s4_y <= {k_s, 8'd0, k_sub};
    end
    // stage 5: output register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin y <= 32'd0; fault <= 1'b0; end
        else begin y <= s4_y; fault <= s4_v && s4_bad; end
    end
endmodule

files.cand_ot_v41_bmul_subnormal_rne_prepare.s:
`timescale 1ns/1ps
// Combinational stage4 subnormal encoder; no state, clock or engine-interface change.
// PREPARE ONLY: contextual stage4 SS/FF/slot closure OPEN. The caller handles nf/zero/overflow/normal.
module cand_ot_v41_bmul_subnormal_rne_prepare (
    input wire sign_i,
    input wire signed [10:0] biased_i,
    input wire [23:0] sig_i,
    output wire [31:0] y
);
    wire signed [10:0] shift_full = 11'sd1 - biased_i;
    wire in_range = shift_full >= 11'sd1 && shift_full <= 11'sd24;
    // Classify at full signed width before narrowing. Invalid shifts use safe indexes.
    wire [4:0] shift_q = in_range ? shift_full[4:0] : 5'd1;
