            .c_i2x_q0(c_i2x_q0), .c_i2x_e0(c_i2x_e0), .c_i2x_q1(c_i2x_q1), .c_i2x_e1(c_i2x_e1), .c_ze_d(c_ze_d),
            .c_so_row(c_so_row), .c_so_idx(c_so_idx), .c_so_n(c_so_n), .c_qy_bkf(c_qy_bkf));
        genvar cm;
        for (cm = 0; cm < NB; cm = cm + 1) begin : g_col
