            .xb_d_pin(xb_d_i), .pv(pv_e), .pval(pval_e), .prow(prow_e), .pseg(pseg_e), .pnseg(pnseg_e), .perr(perr_e),
            .ppos(ppos_e), .busy(busy_e), .fault(fault_e));
